import AppKit

/// The export card's Dynamic Range row (hdr H-3, spec §11 HD-5, HD-14 (h)):
/// "Dynamic Range:" under Format, only in an HLG project, so an SDR project's
/// card is the card it was. On a row that carries HDR (`ExportPreset.carriesHDR`,
/// the four: `hevc_10bit`, `av1`, `prores_422`, `prores_4444`) it offers HDR (HLG), HDR10 (PQ)
/// and SDR version, HDR (HLG) first and the default; on every other row it is
/// disabled and shows "SDR version", the picture that row writes, and sends no
/// override (the core's default for it). The choice lives for the sheet alone:
/// it is not one of `ExportChoice`'s fields, so neither the remembered choice
/// nor a user preset carries it.
extension ExportSheetController {
    /// Whether the document is an HLG project (`canvas.output`), the only
    /// kind of project whose card has the row.
    var isHLGProject: Bool {
        editor?.document?.project.snapshot.canvas.output == .hlg
    }

    /// The popup's items and wiring, in an HLG project only. Called from
    /// `loadView` before the first resolve.
    func configureDynamicRange() {
        guard isHLGProject else { return }
        dynamicRangePopup.addItems(withTitles: DynamicRange.allCases.map { $0.menuName })
        dynamicRangePopup.selectItem(at: 0)
        dynamicRangePopup.font = DS.sans(13)
        dynamicRangePopup.target = self
        dynamicRangePopup.action = #selector(dynamicRangeChanged(_:))
        dynamicRangePopup.widthAnchor.constraint(equalToConstant: 186).isActive = true
    }

    /// A pick on a row that carries HDR: the choice, then a resolve, so the
    /// readout and Export… follow the core's answer for it.
    @objc func dynamicRangeChanged(_ sender: Any?) {
        let index = dynamicRangePopup.indexOfSelectedItem
        guard DynamicRange.allCases.indices.contains(index) else { return }
        dynamicRangeChoice = DynamicRange.allCases[index]
        resolveCard()
    }

    /// The `dynamic_range` override: the choice on a row that carries HDR in
    /// an HLG project, nil everywhere else.
    func dynamicRangeOverride() -> String? {
        guard isHLGProject, currentPreset?.carriesHDR == true else { return nil }
        return dynamicRangeChoice.rawValue
    }

    /// The popup follows the format: live with the choice on a row that
    /// carries HDR, disabled on "SDR version" on any other.
    func syncDynamicRange(_ applies: Applies) {
        guard isHLGProject else { return }
        dynamicRangePopup.isEnabled = applies.dynamicRange
        let shown = applies.dynamicRange ? dynamicRangeChoice : .sdr
        dynamicRangePopup.selectItem(at: DynamicRange.allCases.firstIndex(of: shown) ?? 0)
    }
}
import AppKit

/// The export card's Speed row (codec-export C1, spec §11 CX-2, CX-12 (2)): "Speed:" under
/// Format (after Dynamic Range when an HLG project shows that), offering Faster, Balanced
/// and Smaller file — SVT-AV1's presets 8, 6 and 4 — Balanced the default. It is live only
/// on a row a bundled encoder writes (`ExportPreset.encoderSpeeds`, the `av1` row); on every
/// other row it is disabled and shows the last choice, as Quality does, and sends no
/// override. The choice is remembered with the rest of the card (`ExportChoice`).
extension ExportSheetController {
    /// The popup's items, each carrying its speed, and its wiring. Called from `loadView`
    /// before the remembered choice is applied.
    func configureSpeed() {
        for speed in EncoderSpeed.allCases {
            let item = NSMenuItem(title: speed.menuName, action: nil, keyEquivalent: "")
            item.representedObject = speed.rawValue
            speedPopup.menu?.addItem(item)
        }
        speedPopup.font = DS.sans(13)
        speedPopup.target = self
        speedPopup.action = #selector(speedChanged(_:))
        speedPopup.widthAnchor.constraint(equalToConstant: 186).isActive = true
        syncSpeed(Applies(currentPreset))
    }

    /// A pick: the choice, then a resolve, so the footnote follows the core's echo.
    @objc func speedChanged(_ sender: Any?) {
        guard let raw = speedPopup.selectedItem?.representedObject as? String,
            let speed = EncoderSpeed(rawValue: raw)
        else { return }
        encoderSpeedChoice = speed
        resolveCard()
    }

    /// The `encoder_speed` override: the choice on a row that takes one, nil elsewhere.
    func encoderSpeedOverride() -> String? {
        Applies(currentPreset).encoderSpeed ? encoderSpeedChoice.rawValue : nil
    }

    /// The popup follows the format: live on a row that takes a speed, disabled elsewhere,
    /// showing the choice either way.
    func syncSpeed(_ applies: Applies) {
        speedPopup.isEnabled = applies.encoderSpeed
        let shown = speedPopup.itemArray.first {
            $0.representedObject as? String == encoderSpeedChoice.rawValue
        }
        speedPopup.select(shown)
    }

    /// A stored choice's speed, Balanced when it names none (or one this build lacks).
    func applySpeed(_ choice: ExportChoice) {
        encoderSpeedChoice = choice.encoderSpeed.flatMap(EncoderSpeed.init(rawValue:)) ?? .balanced
    }
}
import AppKit

/// The export card's Bit depth row (road map "audio" AP2 part 2, spec §11 AU-29): "Bit
/// depth:" after Quality, offering 16-bit and 24-bit — the master's rounding from the float
/// mix, never dithered — 16-bit the default. It is live only on a row that lists depths
/// (`ExportPreset.audioBits`, `audio_wav` and `audio_aiff`); on every other row it is
/// disabled and shows the last choice, as Speed does, and sends no override. The choice is
/// remembered with the rest of the card (`ExportChoice`).
extension ExportSheetController {
    /// The two depths the popup offers.
    static let audioBitDepths = [16, 24]

    /// The popup's items, each carrying its depth, and its wiring. Called from `loadView`
    /// before the remembered choice is applied.
    func configureAudioBits() {
        for bits in Self.audioBitDepths {
            let item = NSMenuItem(title: "\(bits)-bit", action: nil, keyEquivalent: "")
            item.representedObject = bits
            audioBitsPopup.menu?.addItem(item)
        }
        audioBitsPopup.font = DS.sans(13)
        audioBitsPopup.target = self
        audioBitsPopup.action = #selector(audioBitsChanged(_:))
        audioBitsPopup.widthAnchor.constraint(equalToConstant: 186).isActive = true
        syncAudioBits(Applies(currentPreset))
    }

    /// A pick: the choice, then a resolve, so the footnote follows the core's echo.
    @objc func audioBitsChanged(_ sender: Any?) {
        guard let bits = audioBitsPopup.selectedItem?.representedObject as? Int else { return }
        audioBitsChoice = bits
        resolveCard()
    }

    /// The `audio_bits` override: the choice on a row that takes one, nil elsewhere.
    func audioBitsOverride() -> Int? {
        Applies(currentPreset).audioBits ? audioBitsChoice : nil
    }

    /// The popup follows the format: live on a row that lists depths, disabled elsewhere,
    /// showing the choice either way.
    func syncAudioBits(_ applies: Applies) {
        audioBitsPopup.isEnabled = applies.audioBits
        let shown = audioBitsPopup.itemArray.first {
            $0.representedObject as? Int == audioBitsChoice
        }
        audioBitsPopup.select(shown)
    }

    /// A stored choice's depth, 16 when it names none (or one this build lacks).
    func applyAudioBits(_ choice: ExportChoice) {
        audioBitsChoice = choice.audioBits.flatMap {
            Self.audioBitDepths.contains($0) ? $0 : nil
        } ?? 16
    }
}
import AppKit

/// The export card's Stems row (road map "audio" AP10 part 2a, spec §11 AU-108): "Stems:"
/// after Bit depth, offering None, One per Track and One per Track Name — files beside the
/// mix, each a track's sound before the master — None the default. It is live only on a row
/// that lists modes (`ExportPreset.stems`, the three audio rows); on every other row it is
/// disabled and shows the last choice, as Bit depth does, and sends no override. The choice
/// is remembered with the rest of the card (`ExportChoice`).
extension ExportSheetController {
    /// The popup's items: its title and the core's word, nil for None.
    static let stemModes: [(title: String, mode: String?)] = [
        ("None", nil), ("One per Track", "tracks"), ("One per Track Name", "names"),
    ]

    /// The popup's items, each carrying its mode, and its wiring. Called from `loadView`
    /// before the remembered choice is applied.
    func configureStems() {
        for (title, mode) in Self.stemModes {
            let item = NSMenuItem(title: title, action: nil, keyEquivalent: "")
            item.representedObject = mode
            stemsPopup.menu?.addItem(item)
        }
        stemsPopup.font = DS.sans(13)
        stemsPopup.target = self
        stemsPopup.action = #selector(stemsChanged(_:))
        stemsPopup.widthAnchor.constraint(equalToConstant: 186).isActive = true
        syncStems(Applies(currentPreset))
    }

    /// A pick: the choice, then a resolve, so the footnote follows the core's echo.
    @objc func stemsChanged(_ sender: Any?) {
        stemsChoice = stemsPopup.selectedItem?.representedObject as? String
        resolveCard()
    }

    /// The `stems` override: the choice on a row that takes one, nil elsewhere.
    func stemsOverride() -> String? {
        Applies(currentPreset).stems ? stemsChoice : nil
    }

    /// The popup follows the format: live on a row that lists modes, disabled elsewhere,
    /// showing the choice either way.
    func syncStems(_ applies: Applies) {
        stemsPopup.isEnabled = applies.stems
        let shown = stemsPopup.itemArray.first {
            $0.representedObject as? String == stemsChoice
        }
        stemsPopup.select(shown)
    }

    /// A stored choice's mode, None when it names none (or one this build lacks).
    func applyStems(_ choice: ExportChoice) {
        stemsChoice = choice.stems.flatMap { stored in
            Self.stemModes.contains { $0.mode == stored } ? stored : nil
        }
    }
}
