        ExportEncoderKey(preset: "vp9_webm", speed: nil, bits: 8): ExportTimeEntry(
            perFrame: ExportEncoderFigure(
                at1080: 7.020 / 250, at2160: 23.549 / 250,
                source: run + "vp9_webm:sdr; load 6.57–26.06 at 1080p, 8.32–39.50 at 4K; C6b"),
