/// The app-wide account of the bundled-encoder exports running now (spec §11 CX-18): the
/// Export Queue's job and every Export… progress sheet's, each booked from just before its
/// exporter starts to its finish, at the resident peak `ExportEncoderCosts.memory` measured
/// for its key and size.
///
/// **Why a ledger and not a pool size.** The queue runs one job at a time (#326, road map
/// 2's 7e) and stays that way; what can run beside its job is an Export… sheet, which a
/// person started and which is never held (CX-18 (6)). So the question a queued AV1 or VP9
/// job asks is not "how many jobs" but "does the memory the others hold, with mine, fit", and
/// the answer has to see the sheets too — which is why the account is one shared object
/// both writers book into, rather than state inside `ExportQueueController`.
///
/// **The budget is a quarter of physical memory**, G-37's share for graphic rasters, so an
/// export's two large consumers stay within half the Mac together. A job is admitted when
/// nothing is booked — one export always runs, however large — or when the booked costs and
/// its own fit.
///
/// Main thread only, like the queue and the sheets that book into it, and AppKit-free so a
/// probe compiles it headless (`tools/proof/encoder_limit_probe.swift`).
final class ExportEncoderLedger {
    /// The app's one ledger. The queue observes it and the sheets book into it.
    static let shared = ExportEncoderLedger()

    /// Posted after a booking is added or removed, with the ledger as the `object`. The
    /// queue re-runs `start()` on it, so a held job launches when a booking ends.
    static let didChangeNotification = Notification.Name(
        "com.kgalligan.framejob.exportEncoderLedgerDidChange")

    /// The Mac's memory the budget is a share of — `ProcessInfo`'s, which a probe sets to
    /// ask what a Mac of another size would admit.
    var physicalMemory: UInt64

    private var entries: [(token: UInt64, cost: UInt64)] = []
    private var nextToken: UInt64 = 1

    init(physicalMemory: UInt64 = ProcessInfo.processInfo.physicalMemory) {
        self.physicalMemory = physicalMemory
    }

    /// What bundled-encoder exports may hold together, in bytes.
    var budget: UInt64 { Self.budget(physicalMemory: physicalMemory) }

    /// Each running booking's cost, in booking order.
    var runningCosts: [UInt64] { entries.map(\.cost) }

    // MARK: - The rule

    /// A quarter of physical memory (CX-18 (3)).
    static func budget(physicalMemory: UInt64) -> UInt64 { physicalMemory / 4 }

    /// Whether a job costing `cost` may start beside `running`: always when nothing runs,
    /// else when the sum fits `budget` (CX-18 (5)).
    static func admits(cost: UInt64, running: [UInt64], budget: UInt64) -> Bool {
        guard !running.isEmpty else { return true }
        let (inUse, over) = running.reduce((UInt64(0), false)) { sum, next in
            let added = sum.0.addingReportingOverflow(next)
            return (added.partialValue, sum.1 || added.overflow)
        }
        let total = inUse.addingReportingOverflow(cost)
        return !over && !total.overflow && total.partialValue <= budget
    }

    /// The held job's sentence: what runs, what the Mac allows, what this one needs.
    static func waitingSentence(cost: UInt64, running: [UInt64], budget: UInt64) -> String {
        let inUse = running.reduce(UInt64(0)) { $0 &+ $1 }
        return "Waiting for memory: AV1 and VP9 exports running now hold about "
            + "\(gigabytes(inUse)) of the \(gigabytes(budget)) this Mac allows them, and this "
            + "one needs about \(gigabytes(cost))."
    }

    private static func gigabytes(_ bytes: UInt64) -> String {
        String(format: "%.1f GB", Double(bytes) / 1_073_741_824)
    }

    // MARK: - Asking

    /// Whether `settings` may start now, leaving out the booking `token` (the queue's own
    /// running job, which a waiting job is behind anyway). True for an AVFoundation row.
    func admits(_ settings: ExportSettings, ignoring token: UInt64? = nil) -> Bool {
        guard settings.writer != nil else { return true }
        return Self.admits(
            cost: ExportEncoderCosts.memoryBytes(for: settings, budget: budget),
            running: costs(ignoring: token), budget: budget)
    }

    /// The held sentence for `settings`, or nil when it is admitted.
    func waitingSentence(for settings: ExportSettings, ignoring token: UInt64? = nil) -> String? {
        guard !admits(settings, ignoring: token) else { return nil }
        return Self.waitingSentence(
            cost: ExportEncoderCosts.memoryBytes(for: settings, budget: budget),
            running: costs(ignoring: token), budget: budget)
    }

    private func costs(ignoring token: UInt64?) -> [UInt64] {
        entries.filter { $0.token != token }.map(\.cost)
    }

    // MARK: - Booking

    /// Books an export about to start and answers its token, or nil — booking nothing —
    /// for an AVFoundation row. Called BEFORE `Exporter.export`, whose early refusals finish
    /// synchronously inside it.
    func begin(_ settings: ExportSettings) -> UInt64? {
        guard settings.writer != nil else { return nil }
        let token = nextToken
        nextToken += 1
        entries.append(
            (token, ExportEncoderCosts.memoryBytes(for: settings, budget: budget)))
        post()
        return token
    }

    /// Ends a booking. A nil or unknown token is a no-op; a removal posts, and the queue's
    /// observer may launch its next job — and book it — inside this call, which is why a
    /// caller clears its own token BEFORE calling this.
    func end(_ token: UInt64?) {
        guard let token, let index = entries.firstIndex(where: { $0.token == token }) else {
            return
        }
        entries.remove(at: index)
        post()
    }

    private func post() {
        NotificationCenter.default.post(name: Self.didChangeNotification, object: self)
    }
}

//!
//! `export.rs` re-exports [`presets`] and [`preset`] at their old names,
//! so `crate::export::presets()` (`ffi_query.rs`) and
//! `crate::export::preset(id)` (`export_size.rs`) resolve exactly as they
//! did — the same trick, and for the same reason, as the `describe`
//! re-export sitting a few lines above them. What the cut did cost is
//! visibility, mechanically: the [`Preset`] fields the resolver reads and
//! the four [`Container`] questions it asks are `pub(crate)` now, where
//! one file had been able to keep them private. [`fps_json`] came across
//! with the table rather than staying with the resolver and is
//! `pub(crate)` for it: both sides spell a rate, and its being one
//! function is the whole of why they cannot disagree about the shape.

use serde_json::Value;

pub(crate) use crate::export_container::Container;
pub(crate) use crate::export_encoder::{EncoderSpeed, Writer};
pub(crate) use crate::export_preset::{fps_json, Preset};
use crate::time::Fps;

/// The §7.8 set: one row per ENCODING, in menu order. A row is a container
/// and a codec and nothing else — no size, no rate — so an export is at the
/// document's own size and rate unless a person asks for another, through
/// the Size popup the sheet fills from `Project::export_sizes` or the
/// overrides a script sends. The size used to be part of the row ("H.264
/// 1080p", "HEVC 4K"), and that shape made the format menu two questions
/// asked as one: picking HEVC meant picking 1080p or 4K with it, and a
/// 1440p or a vertical document had no row that fit it at all. Two
/// questions get two controls, and the format is only ever the encoding.
///
/// The two image rows are the exception and keep a size and a rate,
/// because for them the numbers ARE what makes the row worth having: a GIF
/// or an APNG costs frames × pixels with no inter-frame prediction to
/// spend against, so "at the document's size and rate" is a file no one
/// can send, and the cap is the point of the format rather than a default
/// it happens to carry (§7.8; the row comments argue each number). Both
/// caps are still defaults a size or fps override replaces, and
/// `export_sizes` lists each as the first row of its list.
///
/// The FIRST row is the default: `rc_export_presets` is "in menu order"
/// and the export sheet opens on its first entry, so whatever sits here is
/// what ⌘E writes unless a person picks otherwise. H.264 in MP4 is the
/// file every player and every upload form takes, which is why it leads
/// and HEVC — half the size, not yet everywhere — follows.
///
/// Each movie row carries an `AVAssetExportSession` preset name for the
/// record: the three "highest quality" names are the ones a session would
/// take the composition's own size under rather than fit it to a fixed
/// frame, which is exactly a row with no size of its own. Nothing runs a
/// session any more (§7.8), so on the Swift side the name is only the
/// signal that AVFoundation can write the row at all; the two image rows
/// carry none, which is the signal to write them frame by frame through
/// ImageIO instead. The two LPCM rows repeat `audio_m4a`'s name for the
/// same reason and with the field doc's caveat: AVFoundation has no
/// session preset for LPCM, and a null would route a WAV to ImageIO.
///
/// **No row carries a default bitrate, deliberately.** On the session path
/// the preset name IS the ladder — `AVAssetExportSession` exposes no way to
/// set a rate — so a number here would be one the export cannot honour,
/// which is worse than none at all. On the writer path VideoToolbox derives
/// a rate from the frame size, which beats any constant this table could
/// hold: one that suits 4K wastes half the file at 720p. ProRes is fixed by
/// its profile and ignores a request outright, and GIF and APNG have no
/// bitrate to set. A bitrate is therefore something the user asks for — the
/// `video_bitrate` / `audio_bitrate` overrides — never something a preset
/// assumes on their behalf.
const PRESETS: [Preset; 15] = [
    // The default (see above). The ids are the `export` tool's vocabulary
    // and every script that calls it spells them, so a row is named for
    // the encoding alone — `h264`, not `h264_document` — because the size
    // is no longer anything the id could say.
    Preset {
        id: "h264",
        name: "H.264 (MP4)",
        container: Container::Mp4,
        codec: "h264",
        video: true,
        alpha: false,
        size: None,
        fps: None,
        avf_preset: Some("AVAssetExportPresetHighestQuality"),
        writer: None,
    },
    Preset {
        id: "hevc",
        name: "HEVC (MP4)",
        container: Container::Mp4,
        codec: "hevc",
        video: true,
        alpha: false,
        size: None,
        fps: None,
        avf_preset: Some("AVAssetExportPresetHEVCHighestQuality"),
        writer: None,
    },
    // HEVC with an alpha channel (spec §11 G-33), directly after the row it
    // is a variant of. It is the DELIVERY row that keeps transparency — a
    // title or a lower third a web page or another editor plays over its
    // own background, at HEVC's size where `prores_4444` is a master — and
    // it is a MOV because that is the container AVFoundation writes the
    // codec into (it refuses it an `.mp4`). The codec is spelled as the id
