        container: Container::Mp4,
        codec: "hevc_10bit",
        video: true,
        alpha: false,
        size: None,
        fps: None,
        avf_preset: Some("AVAssetExportPresetHEVCHighestQuality"),
        writer: None,
    },
    // AV1 in MP4 (spec §11 CX-1, CX-12, CX-14), 10-bit, an HDR row through
    // `HDR_ROWS`. SVT-AV1 encodes (`writer`); AVFoundation still writes the
    // container, which is what the passthrough name records, so the row is
    // even-sized and routed as every AVFoundation row is.
    Preset {
        id: "av1",
        name: "AV1 (MP4)",
        container: Container::Mp4,
        codec: "av1",
        video: true,
        alpha: false,
        size: None,
        fps: None,
        avf_preset: Some("AVAssetExportPresetPassthrough"),
        writer: Some(Writer::SvtAv1),
    },
    // AV1 in WebM (spec §11 CX-15): `av1`'s encoding — the same encoder,
    // speeds, cap and HDR — in a WebM the core writes (`webm_writer.rs`),
    // with Opus sound. The passthrough name records that the composition is
    // read back through AVFoundation, so the row is even-sized and routed as
    // every AVFoundation row is until `Exporter.pipeline` reads the container.
    Preset {
        id: "av1_webm",
        name: "AV1 (WebM)",
        container: Container::Webm,
        codec: "av1",
        video: true,
        alpha: false,
        size: None,
        fps: None,
        avf_preset: Some("AVAssetExportPresetPassthrough"),
        writer: Some(Writer::SvtAv1),
    },
    // VP9 in WebM (spec §11 CX-16): libvpx at its one speed (CX-3) into the
    // same core-written WebM with Opus; Profile 0 8-bit for an SDR picture,
    // Profile 2 10-bit for HLG and PQ, so an HDR row.
    Preset {
        id: "vp9_webm",
        name: "VP9 (WebM)",
        container: Container::Webm,
        codec: "vp9",
        video: true,
        alpha: false,
        size: None,
        fps: None,
        avf_preset: Some("AVAssetExportPresetPassthrough"),
        writer: Some(Writer::Libvpx),
    },
    // VP9 with alpha in WebM (spec §11 CX-17): `vp9_webm`'s 8-bit Profile 0
    // picture and a second libvpx stream of its alpha, written as each video
    // block's BlockAdditional 1 — the format Chrome and Firefox play with
    // transparency. One of the four rows with a fourth channel, so the shape
    // rule binds it; 8-bit SDR only, so not an HDR row: an HLG project writes
    // the SDR version.
    Preset {
        id: "vp9_alpha_webm",
        name: "VP9 with Alpha (WebM)",
        container: Container::Webm,
        codec: "vp9",
        video: true,
        alpha: true,
        size: None,
        fps: None,
        avf_preset: Some("AVAssetExportPresetPassthrough"),
        writer: Some(Writer::Libvpx),
    },
    Preset {
        id: "prores_422",
        name: "ProRes 422 (MOV)",
        container: Container::Mov,
        codec: "prores422",
        video: true,
        alpha: false,
        size: None,
        fps: None,
        avf_preset: Some("AVAssetExportPresetAppleProRes422LPCM"),
        writer: None,
    },
    // The MASTERING row that keeps transparency (road map 2, phase 7) —
    // one of the four rows with a fourth channel and not the only one:
    // `hevc_alpha` and `vp9_alpha_webm` above and `apng` below carry one too
    // and say so at their own rows. The four are not redundant, which is why
    // no row's comment may be written as if it were alone: this is a MASTER,
    // in a container AVFoundation writes, whose next reader is another
    // application; `hevc_alpha` is the delivery movie and `vp9_alpha_webm`
    // the browser's; and `apng` is a frame sequence with a null `avf_preset`
    // and no audio track at all. `alpha`'s field doc holds the rule all four
    // answer to, and `core/tests/export.rs` pins the four by name.
    //
    // ProRes 4444 is a master or an intermediate: a file whose next
    // reader is another application rather than a viewer — a lower third
    // or a title card cut over somebody else's footage, a screencast going
    // back into a compositor, a graphic handed to a motion designer. The
    // fourth channel is the whole of why it earns a row beside
    // `prores_422`, which shares its container, its colour and its
    // editing-master posture and differs in exactly this: 422 cannot carry
    // alpha at any bitrate. Nor can the `h264` or `hevc` row stand in —
    // neither has an alpha channel in the profile `ExporterWriter` writes
    // for it, so an export of a transparent canvas through one of them is
    // a picture flattened onto black with no way back. `hevc_alpha` does
    // keep the channel, as a lossy 8-bit 4:2:0 delivery file, which is not
    // what a master is.
    //
    // It sits AFTER 422 rather than before it because a row's position is
    // an invitation: most exports of a finished timeline have nothing
    // under them and want the smaller of the two files, so 422 stays the
    // ProRes people reach for first and 4444 is the one you go looking for
    // when you need the channel.
    Preset {
        id: "prores_4444",
        name: "ProRes 4444 (MOV)",
        container: Container::Mov,
        // The spelling `ExporterWriter.codecType(for:)` already maps to
        // `AVVideoCodecType.proRes4444`; it accepts `prores_4444` too, and
        // this one is chosen for the same reason `prores422` is — the
        // codec field is the codec's own name, where the underscore-and-id
        // spelling is the PRESET's.
        codec: "prores4444",
        video: true,
        alpha: true,
        size: None,
        fps: None,
        // Non-null, and not optional: a null `avf_preset` is the ONE
        // routing signal to the ImageIO writer (`avf_preset`'s field doc),
        // which would meet a `"mov"` container it has never heard of and
        // refuse a format this table advertises. The name is
        // AVFoundation's real ProRes 4444 preset and is a record of what
        // writes the row, nothing more — nothing has run a session since
        // M2.
        avf_preset: Some("AVAssetExportPresetAppleProRes4444LPCM"),
        writer: None,
    },
    Preset {
        id: "audio_m4a",
        name: "Audio only (M4A)",
        container: Container::M4a,
        codec: "aac",
        video: false,
        alpha: false,
        size: None,
        fps: None,
        avf_preset: Some("AVAssetExportPresetAppleM4A"),
        writer: None,
    },
    // The two uncompressed audio rows (road map 2, phase 5). M4A is what
    // you send; these are what you hand to someone else's tool — a mix
    // going out to a mastering engineer, a bed going into a podcast
    // editor, a stem a DAW will re-encode anyway — where a second lossy
    // generation is the one thing you cannot take back.
    //
    // The codec is `lpcm`, not a container spelling, because the container
    // and the codec are separate questions here and `ExportWriter` has to
    // answer the codec one to pick its `AVAssetWriterInput` settings: the
    // mix is read as float and quantised once by the export's master
    // (spec §11 AU-27) to interleaved 48 kHz LPCM, so a WAV is those
    // samples little-endian and an AIFF the same samples big-endian, which
    // the CONTAINER decides.
    //
    // 16-bit by default, and 24 an override rather than a row: the
    // `audio_bits` request beside the bitrates (AU-29), offered on these
    // two rows only (`Preset::takes_audio_bits`).

    /// The reader output the video pump reads: the composition's video tracks
    /// through the video composition (`videoComposition`), in the one format
    /// the compositor produces. `ExportWebMWriter` reads through it too.
    static func videoReadOutput(
        _ built: BuiltComposition, settings: ExportSettings
    ) -> AVAssetReaderVideoCompositionOutput {
        let output = AVAssetReaderVideoCompositionOutput(
            videoTracks: built.composition.tracks(withMediaType: .video),
            videoSettings: [
                // The one format the compositor produces (`Compositor.
                // outputPixelFormat`, 64RGBAHalf). Asking for it here means no
                // conversion between the render context and the encoder.
                kCVPixelBufferPixelFormatTypeKey as String: Int(Compositor.outputPixelFormat),
                kCVPixelBufferMetalCompatibilityKey as String: true,
            ])
        output.videoComposition = videoComposition(built, settings: settings)
        // AVFoundation's default, kept explicit: `ExportStraightAlpha` rewrites an
        // alpha row's frame in place, which is safe only on the reader's own copy.
        output.alwaysCopiesSampleData = true
        return output
    }

    /// The mix's reader output: every composition audio track through the
    /// plan's mix, as the float mix the measurement read
    /// (`ExportAudioMaster.floatMixSettings`, spec §11 AU-27), which the
    /// master turns into the encoder's samples. `ExportWebMWriter` reads
    /// through it too. A stem's build (`audioSelection`, spec §11 AU-108 (e))
    /// reads only its own tracks through a mix of only their parameters, and
    /// so does a sub-mix of `ExportMixRead` (`only`, AU-152), both at once
    /// for a stem's sub-mix.
    static func audioReadOutput(
        _ built: BuiltComposition, only: Set<CMPersistentTrackID>? = nil
    ) -> AVAssetReaderAudioMixOutput {
        var tracks = built.composition.tracks(withMediaType: .audio)
        var mix = built.audioMix
        if built.audioSelection != nil || only != nil {
            let reads = { (id: CMPersistentTrackID) in
                (built.audioSelection?.contains(id) ?? true) && (only?.contains(id) ?? true)
            }
            tracks = tracks.filter { reads($0.trackID) }
            let selected = AVMutableAudioMix()
            selected.inputParameters = built.audioMix.inputParameters.filter {
                reads($0.trackID)
            }
            mix = selected
        }
        let output = AVAssetReaderAudioMixOutput(
            audioTracks: tracks, audioSettings: ExportAudioMaster.floatMixSettings)
        output.audioMix = mix
        // AVFoundation's own default, kept explicit because the other reader
        // in this tree (`MediaImporter.peaks`) turns it off.
        output.alwaysCopiesSampleData = true
        return output
    }

    /// Refuses an alpha-carrying export whose size would have to be PADDED
    /// (road map 2, phase 7b; `Exporter.ExportError.alphaAspectMismatch`
    /// carries the argument and the measurement).
    ///
    /// The composition renders at the canvas size and
    /// `AVVideoScalingModeResizeAspect` fits it into the asked-for frame —
    /// which is right for an opaque row, and destroys the alpha channel
    /// when it has to pad: the picture comes back at alpha 0 and the bars at
    /// alpha 255, the answer inverted. A pure SCALE is safe at any factor,
    /// up or down, so what is refused is the shape change and not the
    /// resize.
    ///
    /// The test is `shapeGap`'s, the one `fillsTheBox` asks too (spec §11
    /// G-33 (c)): a frame of the canvas's exact shape is written as it is, a
    /// frame within a pixel of it is FILLED, and only a frame further off —
    /// `gap > limit` — would be padded, which is what is refused here. So an
    /// alpha row is exact or filled and never padded, and it reaches
    /// `hevc_alpha` as it reaches `prores_4444`, because the row's `alpha`
    /// is true.
    ///
    /// **The box is `encodedSize`'s and not `settings`'.** The encoder is
    /// handed `AVVideoWidthKey`/`AVVideoHeightKey`, and it is that frame's
    /// shape the picture has to meet. On settings the core resolved the two
    /// are one pair (G-33 (b): the core evens the size on the rows that need
    /// it, and ProRes 4444 keeps an odd edge), so asking `encodedSize` is the
    /// floor under any other caller: a rounding there moves the box, and a
    /// comparison against `settings` would not see it. An odd-edged
    /// transparent document is legal — `set_canvas` refuses an odd dimension,
    /// `Project::new` and `validate` do not, so an odd-sized PNG opened as a
    /// document or an odd display size gets one — and at 1001 × 667 its
    /// Document row is 1001 × 667 on ProRes 4444, the canvas's exact shape,
    /// and the evened 1000 × 666 on `hevc_alpha`, within a pixel and filled.
    ///
    /// **The pixel of slack does not cost an edge.** It is there for
    /// `export_size.rs`'s even-rounding — a standard row's long edge, the
    /// evened Document row on a canvas with an odd edge, and an odd size
    /// typed in the canvas's proportions can each miss the canvas's exact
    /// shape by a pixel, and refusing them would be a false refusal. A frame
    /// inside the slack is FILLED (`videoSettings`),
    /// so every edge of it is the picture's; fitted, the pad put an edge
    /// column at the backdrop's alpha instead (ProRes 4444 at 255,
    /// `hevc_alpha` up to 16, where the canvas is transparent — G-33 (c)).
    /// `hevc_alpha_proof.py`'s rows O1, O4, O5, P1 and P2 read all four
    /// edges of such files at alpha 0.
    static func checkAlphaSurvivesTheSize(
        _ settings: ExportSettings, canvas: CGSize
    ) throws {
        guard settings.alpha, canvas.width >= 1, canvas.height >= 1,
            settings.width >= 1, settings.height >= 1
        else { return }
        let shape = shapeGap(encodedSize(settings), canvas: canvas)
        guard shape.gap > shape.limit else { return }
        // The MESSAGE names `settings`' size and not the box. That is the
        // size the core RESOLVED (spec §11 G-33): on ProRes 4444, which
        // keeps an odd edge, the pair that was asked for — so the sentence
        // still tells the person what to type instead, with no number in it
        // they never typed — and on a row the core evens, the even pair the
        // sheet and the `export` tool reported.
        throw Exporter.ExportError.alphaAspectMismatch(
            width: Int(canvas.width.rounded()), height: Int(canvas.height.rounded()),
            wantWidth: settings.width, wantHeight: settings.height)
    }

    /// How far a frame is from the canvas's shape, and how far counts as
    /// "within a pixel" — the ONE shape test, in integers, which the alpha
    /// guard and the scaling mode both ask (spec §11 G-33 (c)). Nothing else
    /// compares shapes.
    ///
    /// With `cw` × `ch` the canvas and `bw` × `bh` the frame,
    /// `d = bw·ch − bh·cw` and `gap = |d|`; 0 is the canvas's exact shape.
    /// When `d > 0` the frame is wider than the canvas's shape: a fit leaves
    /// `gap/ch` px of width uncovered and a fill overshoots the height by
    /// `gap/cw` px; when `d < 0` it is the other way round. `limit` has two
    /// arms. A canvas-SHAPED size less at most one pixel on each axis —
    /// `(bw + a)·ch == (bh + b)·cw` for some `a`, `b` in {0, 1}: the evened
    /// Document row, an odd size typed in the canvas's own proportions once
    /// the core has evened it (720 × 405 on 1920 × 1080 arrives as
    /// 720 × 404), and on ProRes 4444 a typed frame one pixel short —
    /// `max(cw, ch)`: the fit leaves at most a pixel OR the fill overshoots
    /// by at most one. There `gap` is `|b·cw − a·ch|`, never above the
    /// limit, so such a frame is always exact or filled. Any other frame:
    /// `ch` when `d > 0`, else `cw` — the fit leaves at most a pixel, which
    /// is the phase-7b guard in integers. `gap <= limit` is "within a
    /// pixel", and it is `<=` on purpose: an evened canvas whose odd edge is
    /// the SHORT one sits exactly on the limit (181 × 320 into 180 × 320:
    /// gap 320, limit 320).
    ///
    /// The first arm is what lets an evened size through — fitted, it can
    /// miss by more than a pixel (1.77 px at 181 × 320) — at ANY scale,
    /// smaller than the canvas or larger, because a size of the canvas's
    /// shape is never refused for being odd (the owner's answer). Swift is
    /// handed only the even frame, so on 400 × 100 it cannot tell a typed
    /// 396 × 98 or 404 × 100 from an evened 396 × 99 or 404 × 101: those are
    /// filled too, on every row, where they were letterboxed — the costs
    /// G-33 (c) records as accepted. A frame typed to pad the canvas by any
    /// other amount (402 × 100 on 400 × 100: gap 200, limit 100) is
    /// letterboxed as it always was. The quotients are arithmetic, not what
    /// the scaler cuts: it drops whole source pixels and stretches the rest
    /// (G-33 (c) has the measurement).
    private static func shapeGap(
        _ frame: (width: Int, height: Int), canvas: CGSize
    ) -> (gap: Int, limit: Int) {
        let cw = max(1, Int(canvas.width.rounded()))
        let ch = max(1, Int(canvas.height.rounded()))
        let d = frame.width * ch - frame.height * cw
        // (bw + a)·ch == (bh + b)·cw for some a, b in {0, 1} is d == b·cw − a·ch.
        let inside = [0, cw, -ch, cw - ch].contains(d)
        let limit = inside ? max(cw, ch) : (d > 0 ? ch : cw)
        return (abs(d), limit)
    }

    /// Whether the picture FILLS the frame rather than being fitted inside
    /// it: a frame within a pixel of the canvas's shape and not exactly it
    /// (`shapeGap`). No codec is asked — an opaque row fills where it used to
    /// write a black line, an alpha row where it used to write an edge at the
    /// wrong alpha.
    static func fillsTheBox(_ settings: ExportSettings, canvas: CGSize) -> Bool {
        let shape = shapeGap(encodedSize(settings), canvas: canvas)
        return shape.gap > 0 && shape.gap <= shape.limit
    }

    /// The frame the ENCODER is given, and the ONE place that is decided,
    /// because a second opinion about it is exactly what
    /// `checkAlphaSurvivesTheSize` was missing.
    ///
    /// **The core has already evened the size** (spec §11 G-33). On every row
    /// that needs even dimensions `rc_export_settings` resolves an odd edge
    /// one pixel smaller — a standard row, the Document row and a custom size
    /// alike (`export_size.rs`'s `even_size`, which is `evenDimension`'s
    /// arithmetic) — so on what the core answers this function is the
    /// IDENTITY, and the size the sheet, the queue and the `export` tool
    /// report is the frame the file has. The rounding stays as the floor
    /// under any caller that hands in settings the core did not resolve:
    /// H.264 and HEVC require even dimensions whoever asks.
    ///
    /// **ProRes 4444 keeps its odd edges, and that is the fix rather than a
    /// preference.** Rounding an odd edge down moves the box, and a picture
    /// FITTED into the moved box is padded by the pixel the rounding took
    /// away — and padding is the one thing an alpha export cannot survive.
    /// Measured here (macOS 26.5.1, `AVAssetWriter` +
    /// `AVVideoCodecType.proRes4444`): asked for 1001 × 667 the writer
    /// accepts it and the file comes back `prores`, `yuva444p12le`,
    /// 1001 × 667, with the transparent half at alpha 0 and the opaque half
    /// at 255 — exact at every pixel; asked for 1000 × 666 with the same
    /// 1001 × 667 picture, fitted, it came back with its right-hand column
    /// OPAQUE where the canvas is transparent. So the one row that could not
    /// afford the rounding turns out not to need it — and since G-33 a frame
    /// a pixel short is filled rather than fitted, so the master keeps its
    /// odd edge because it can be the document's own pixels, not because the
    /// rounding would still break it.
    /// Every other row keeps the rounding it has always had, ProRes 422
    /// included — it does not need it either (measured: 1001 × 667 survives
    /// as `yuv422p10le`), but changing the bytes a shipped row writes for a
    /// case no proof covers is not this guard's business.
    static func encodedSize(_ settings: ExportSettings) -> (width: Int, height: Int) {
        guard codecType(for: settings.codec) == .proRes4444 else {
            return (evenDimension(settings.width), evenDimension(settings.height))
        }
        return (max(1, settings.width), max(1, settings.height))
    }

    /// The encoder settings for the picture.
    ///
    /// **Size.** The composition renders at the CANVAS size (§7.2), and the
    /// core resolves the export size — the document's unless the sheet's
    /// Size popup, its Custom fields or the `export` tool asked for another
    /// — and they are not the same number; the session path simply dropped
    /// the second one on the floor: the preset scaled to fit whatever it
    /// liked, so the sheet's "1920 × 1080" was a wish. Here the encoder is
    /// told the size the sheet promised, and the scaling mode is one of two
    /// (spec §11 G-33 (c)). A frame of the canvas's exact shape, or one more
    /// than a pixel off it, gets `AVVideoScalingModeResizeAspect`: the canvas
    /// fitted inside, letterboxed rather than distorted when the two shapes
    /// differ. A frame WITHIN a pixel of the canvas's shape (`fillsTheBox`)
    /// gets `AVVideoScalingModeResizeAspectFill`: the picture covers the
    /// frame, where a fit wrote one or two black lines along an edge — the
    /// evened Document row on a canvas with an odd edge, an odd size typed
    /// in the canvas's proportions, and a standard row whose long edge
    /// rounded. The frame itself is `encodedSize`'s answer,
    /// because `checkAlphaSurvivesTheSize` and `fillsTheBox` have to compare
    /// against the same number.
    ///
    /// **HEVC with alpha** is the HEVC row's dictionary — the bit rate, the
    /// key-frame interval, the expected frame rate — plus the one key that
    /// says what the pixels handed to the encoder ARE: straight, because the
    /// video pump un-premultiplies an alpha row's frames first
    /// (`ExportStraightAlpha`, spec §11 G-35 (e), amending G-33 (d)). There
    /// is no alpha-quality key and no profile key (G-33 (d) has what was
    /// measured with and without).
    ///
    /// **Bitrate.** `settings.videoBitrate` when the core resolved one. When
    /// it did not, a rate computed from the frame — bits per pixel per frame,
    /// halved for HEVC — rather than none at all: with no
    /// `AVVideoAverageBitRateKey` VideoToolbox picks a conservative default
    /// that visibly under-runs a 4K timeline. ProRes gets neither: its rate
    /// is a property of the profile.
    static func videoSettings(
        _ settings: ExportSettings, canvas: CGSize
    ) throws -> [String: Any] {
        guard let codec = codecType(for: settings.codec) else {
            throw Exporter.ExportError.presetUnavailable(presetName(settings))
        }
        let frame = encodedSize(settings)
        let fills = fillsTheBox(settings, canvas: canvas)
        var output: [String: Any] = [
            AVVideoCodecKey: codec,
            AVVideoWidthKey: frame.width,
            AVVideoHeightKey: frame.height,
            AVVideoScalingModeKey: fills
                ? AVVideoScalingModeResizeAspectFill : AVVideoScalingModeResizeAspect,
            // The compositor works in SDR 709 and converts HDR sources itself
            // at step 0 (GR-15, §7.5), so tagging the output 709 is a
            // statement of what the pixels ARE, not a conversion.
            AVVideoColorPropertiesKey: [
                AVVideoColorPrimariesKey: AVVideoColorPrimaries_ITU_R_709_2,
                AVVideoTransferFunctionKey: AVVideoTransferFunction_ITU_R_709_2,
                AVVideoYCbCrMatrixKey: AVVideoYCbCrMatrix_ITU_R_709_2,
            ],
        ]
        // An HLG project's 10-bit row (spec §11 HD-13 (j), HD-14 (c), the
        // core's `color`): its pixels are HLG or PQ over BT.2020, and so are
        // its tags; its SDR version (`sdr`) keeps the BT.709 tags above.
        let hlg = settings.color == "hlg"
        let pq = settings.color == "pq"
        if hlg || pq {
            output[AVVideoColorPropertiesKey] = [
                AVVideoColorPrimariesKey: AVVideoColorPrimaries_ITU_R_2020,
                AVVideoTransferFunctionKey: pq
                    ? REDACTED : REDACTED,
                AVVideoYCbCrMatrixKey: AVVideoYCbCrMatrix_ITU_R_2020,
            ]
        }
        // HDR10's fixed metadata (spec §11 HD-5, HD-14 (d)): ProRes takes the
        // two keys as a compression dictionary of their own (measured, M7).
        if pq, codec == .proRes422 || codec == .proRes4444 {
            output[AVVideoCompressionPropertiesKey] = hdr10Metadata
        }
        guard codec != .proRes422, codec != .proRes4444 else { return output }

        var compression: [String: Any] = [
            AVVideoAverageBitRateKey: settings.videoBitrate.map { max(1, $0) }
                ?? defaultVideoBitrate(settings, codec: codec),
            // A keyframe at least every two seconds. Deliberate, not a
            // default: an exported movie is scrubbed and re-cut, and
            // VideoToolbox's own interval is long enough to make that
            // painful.
            AVVideoMaxKeyFrameIntervalDurationKey: 2.0,
        ]
        if settings.fps.double > 0 {
            compression[AVVideoExpectedSourceFrameRateKey] = Int(settings.fps.double.rounded())
        }
        if codec == .h264 {
            compression[AVVideoProfileLevelKey] = AVVideoProfileLevelH264HighAutoLevel
        }
        // Pinned to 8-bit Main (spec §11 PR-3): given no profile, VideoToolbox
        // follows its input's format, and the compositor's 16-bit frames
        // gave Main 10. `frameForm` rounds this row's frame to 8 bits as
        // well; the pin is what holds Main if a deep frame ever reaches it.
        // `hevc_10bit` is the same codec pinned to Main 10, fed deep frames.
        if codec == .hevc, isMain10(settings) {
            compression[AVVideoProfileLevelKey] = kVTProfileLevel_HEVC_Main10_AutoLevel as String
        } else if codec == .hevc {
            compression[AVVideoProfileLevelKey] = kVTProfileLevel_HEVC_Main_AutoLevel as String
        }
        if codec == .hevcWithAlpha {
            compression[kVTCompressionPropertyKey_AlphaChannelMode as String] =
                kVTAlphaChannelMode_StraightAlpha
        }
        // Dolby Vision off (spec §11 HD-5, choice 5a): without the key
        // VideoToolbox adds a profile 8.4 configuration and RPU frames to an
        // HLG HEVC Main 10 file by itself (the brief's M7).
        if hlg, codec == .hevc {
            compression[kVTCompressionPropertyKey_HDRMetadataInsertionMode as String] =
                kVTHDRMetadataInsertionMode_None
        }
        // HDR10's metadata beside the other keys, with NO insertion-mode key:
        // explicit values are written exactly and no Dolby Vision is added
        // (spec §11 HD-14 (f), measured).
        if pq, codec == .hevc {
            compression.merge(hdr10Metadata) { _, metadata in metadata }
        }
        output[AVVideoCompressionPropertiesKey] = compression
        return output
    }

    /// HDR10's mastering display and content light level as VideoToolbox's
    /// two compression keys (`OutputTransform`'s blobs, spec §11 HD-14 (d)).
    static var hdr10Metadata: [String: Any] {
        [
            kVTCompressionPropertyKey_MasteringDisplayColorVolume as String:
                OutputTransform.masteringDisplay,
            kVTCompressionPropertyKey_ContentLightLevelInfo as String:
                OutputTransform.contentLightLevel,
        ]
    }

    /// What the video pump makes of each 64RGBAHalf frame before the encoder
    /// (spec §11 PR-3, `ExportFrames`): `hevc_alpha`'s rounded to 8 bits and
    /// straightened, any other alpha row's (`prores_4444`) straightened in
    /// float, `h264`'s and `hevc`'s rounded to 8 bits; nil hands the frame on
    /// as drawn. The two 8-bit codecs encode a ramp worse from half-float
    /// frames: H.264 8.80 steps RMS against 6.27 from 32BGRA, and `hevc`
    /// (Main) 9.04 against 6.46 (precision PR1). `hevc_10bit` maps to `.hevc`
    /// too, so it is asked by its codec NAME first: Main 10 takes the deep
    /// frames, which is the row's whole point.
    static func frameForm(_ settings: ExportSettings) -> ExportFrameForm? {
        let codec = codecType(for: settings.codec)
        if settings.alpha { return codec == .hevcWithAlpha ? .straightEightBit : .straightHalf }
        if isMain10(settings) { return nil }
        return codec == .h264 || codec == .hevc ? .eightBit : nil
    }

    /// Whether the row is `hevc_10bit` (spec §11 PR-3): `.hevc` with the
    /// Main 10 profile and the compositor's frames as drawn. Asked by the
    /// codec name because `codecType(for:)` answers `.hevc` for both HEVC rows.
    private static func isMain10(_ settings: ExportSettings) -> Bool {
        settings.codec.lowercased() == "hevc_10bit"
    }

    /// The core's codec name as an `AVVideoCodecType`. nil is a refusal, not
    /// a fallback: writing H.264 because "vp9" was not understood would put a
    /// file on disk that is not the one asked for.
    private static func codecType(for codec: String) -> AVVideoCodecType? {
        switch codec.lowercased() {
        case "h264", "avc", "avc1": return .h264
        case "hevc", "h265", "hvc1": return .hevc
        case "hevc_alpha": return .hevcWithAlpha
        case "hevc_10bit": return .hevc
        case "prores_422", "prores", "prores422": return .proRes422
        case "prores_4444", "prores4444": return .proRes4444
        default: return nil
        }
    }

    /// What to call the settings in a refusal: the core's preset id when it
    /// gave one, else the codec that could not be written.
    static func presetName(_ settings: ExportSettings) -> String {
        settings.preset.isEmpty ? settings.codec : settings.preset
    }

    /// Bits per second for a frame of this size at this rate. The constants
    /// are the usual delivery figures — about 9 Mbps for 1080p30 H.264 and
    /// half that for HEVC, with or without alpha — clamped so a tiny canvas
    /// still gets a usable rate and a huge one cannot ask for a file no disk
    /// wants.
    private static func defaultVideoBitrate(
        _ settings: ExportSettings, codec: AVVideoCodecType
    ) -> Int {
        let perPixel = (codec == .hevc || codec == .hevcWithAlpha) ? 0.07 : 0.14
        return defaultVideoBitrate(settings, bitsPerPixel: perPixel)
    }

    /// The same rate at `bitsPerPixel` per frame — the AV1 row's "Format
    /// default" is HEVC's 0.07 (spec §11 CX-9 (2)).
    static func defaultVideoBitrate(_ settings: ExportSettings, bitsPerPixel: Double) -> Int {
        let pixels = Double(max(1, settings.width)) * Double(max(1, settings.height))
        let rate = settings.fps.double > 0 ? settings.fps.double : 30
        return Int(min(max(pixels * rate * bitsPerPixel, 1_000_000), 200_000_000))
    }

    /// Even, and never zero — H.264 and HEVC macroblocks come in pairs.
    /// `encodedSize` is the only caller and says which rows want it.
    private static func evenDimension(_ value: Int) -> Int {
        let clamped = max(2, value)
        return clamped - (clamped % 2)
    }

    /// The shape of the master's 16-bit output (`ExportAudioMaster`, spec §11
    /// AU-27): 48 kHz, 2 channels, 16-bit interleaved little-endian LPCM. The
    /// same format the ProRes path writes, and the one AAC, Opus and ProRes
    /// are fed. Nothing reads the mix in it any more: every export reads the
    /// float mix and the master quantises it once, after the gain and the
    /// limiter (#86). A 24-bit WAV or AIFF is the same shape at 24 bits
    /// (`audioSettings`, AU-29).
    static let decodedAudioSettings: [String: Any] = [
        AVFormatIDKey: Int(kAudioFormatLinearPCM),
        AVSampleRateKey: 48000,
        AVNumberOfChannelsKey: 2,
        AVLinearPCMBitDepthKey: 16,
        AVLinearPCMIsFloatKey: false,
        AVLinearPCMIsBigEndianKey: false,
        AVLinearPCMIsNonInterleaved: false,
    ]

    /// The encoder settings for the sound: LPCM where the row asks for it, so
    /// a master stays a master, and AAC everywhere else. `settings.audioBitrate`
    /// when the core resolved one, else 192 kbps — stereo AAC's
    /// transparent-enough rate and what the M1 presets landed on.
    ///
    /// **Two codecs mean LPCM (`ExportSettings.carriesLinearPCM(codec:)`), and
    /// the CONTAINER decides the byte order.** ProRes has since M2 (§7.8
    /// pairs the profile with uncompressed sound), and phase 5's `audio_wav`
    /// / `audio_aiff` rows carry the codec `lpcm` outright. The dictionary handed to the encoder is then literally
    /// `decodedAudioSettings` — at 24 bits when `settings.audioBits` asks
    /// (spec §11 AU-29) — so nothing is converted on the way:
    /// `ExportAudioMaster` produces that shape from the float read. The exception is
    /// AIFF, which is big-endian by definition where WAV and QuickTime are
    /// little. Getting that flag wrong is not a subtle bug, and it was measured rather than
    /// reasoned about: on macOS 26.5.1 `AVAssetWriter.canAdd` answers FALSE
    /// for AAC settings into a `.wav` and FALSE for a little-endian LPCM
    /// dictionary into an `.aiff`, so either mistake reaches the user as
    /// `.presetUnavailable` for a format the table advertises. With the
    /// branch as written, one twenty-second tone came out of both rows the
    /// same size and decoded to identical PCM, sample for sample.
    ///
    /// A row whose codec is `lpcm` in a container this build has no rule for
    /// still gets little-endian LPCM rather than AAC, because AAC in an
    /// uncompressed container is the failure that reads as
    /// `.presetUnavailable` and sends the reader looking at the preset table.
    static func audioSettings(_ settings: ExportSettings) -> [String: Any] {
        guard ExportSettings.carriesLinearPCM(codec: settings.codec) else {
            return [
                AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                AVSampleRateKey: 48000,
                AVNumberOfChannelsKey: 2,
                AVEncoderBitRateKey: settings.audioBitrate.map { max(1, $0) } ?? 192_000,
            ]
        }
        var lpcm = decodedAudioSettings
        if settings.audioBits == 24 { lpcm[AVLinearPCMBitDepthKey] = 24 }
        if settings.container.lowercased() == "aiff" { lpcm[AVLinearPCMIsBigEndianKey] = true }
        return lpcm
    }

    /// Whether this container can hold a chapter track (see `addChapters`).
    /// The QuickTime family and nothing else: a chapter list is a text track
    /// associated with the movie's own, and WAV, AIFF and the two image
    /// formats have no track to associate it with.
    static func carriesChapters(_ settings: ExportSettings) -> Bool {
        switch settings.container.lowercased() {
        case "mov", "quicktime", "mp4", "m4v", "m4a": return true
        default: return false
        }
    }
}
import AppKit

/// The export values the core's presets and settings decode into — `ExportPreset`,
/// `ExportSettings` and `ExportSize` — moved out of `ReelCore.swift` (a pure move, hdr H-1)
/// because they name no `rc_*` symbol; `ReelExport` there still reads them.
/// One row of `rc_export_presets`. Decoded leniently: the core owns this
/// schema (§7.8) and may add fields this build does not know.
struct ExportPreset: Decodable, Equatable, Identifiable {
    let id: String
    let name: String
    /// "mov", "mp4", "m4a".
    let container: String
    /// "h264", "hevc", "prores_422", "aac".
    let codec: String
    /// Fixed output size, or nil for the document (canvas) size.
    let width: Int?
    let height: Int?
    let audioOnly: Bool
    /// Whether the row carries an HLG project's HDR picture (`"hdr"`, spec §11
    /// HD-14 (c), CX-14, CX-16): the six HDR rows (`hevc_10bit`, `av1`,
    /// `av1_webm`, `vp9_webm`, `prores_422`, `prores_4444`), which offer the
    /// Dynamic Range popup.
    let carriesHDR: Bool
    /// The bundled encoder's speeds the row takes (`encoder_speeds`, spec §11
    /// CX-12 (2)): the AV1 rows' three, which offer the Speed popup; empty
    /// elsewhere, `vp9_webm` included (CX-16 (2)).
    let encoderSpeeds: [EncoderSpeed]
    /// The bundled encoder that writes the row's video (`writer`, spec §11
    /// CX-12 (1), CX-16): "svt_av1" or "libvpx"; nil on every row AVFoundation
    /// encodes. A row with one has a soft-cap rate (CX-13).
    let writer: String?
    /// The bit depths the row offers (`audio_bits`, spec §11 AU-29): [16, 24]
    /// on `audio_wav` and `audio_aiff`, which offer the Bit depth popup; empty
    /// elsewhere.
    let audioBits: [Int]

        codec = c.lenient(.codec, "h264")
        let size: [Int]? = c.lenient(.size)
        width = size?.count == 2 ? size?[0] : nil
        height = size?.count == 2 ? size?[1] : nil
        audioOnly = !c.lenient(.video, true)
        carriesHDR = c.lenient(.hdr, false)
        let speeds: [String] = c.lenient(.encoderSpeeds, [])
        encoderSpeeds = speeds.compactMap(EncoderSpeed.init(rawValue:))
        writer = c.lenient(.writer)
        audioBits = c.lenient(.audioBits, [])
        stems = c.lenient(.stems, [])
    }
}

/// One stem an audio export writes beside its mix (spec §11 AU-108): its file
/// name's tail and the timeline track ids it holds, as the core resolved them.
struct ExportStem: Decodable, Equatable {
    let name: String
    let tracks: [UInt32]
}

/// A preset plus overrides resolved against the project into the concrete
/// numbers `Exporter` configures its pipeline with — `ExportWriter` or the
/// ImageIO frame sequence (§7.8).
struct ExportSettings: Decodable, Equatable {
    let preset: String
    let container: String
    let codec: String
    let width: Int
    let height: Int
    let fps: Fps
    /// The range to write — the whole timeline, or the in/out range.
    let start: Ticks
    let duration: Ticks
    /// The `AVAssetExportSession` preset name the row carries for the
    /// record; nil is the signal that AVFoundation cannot write this
    /// container and the frames go through ImageIO (`isImageSequence`).
    let avPreset: String?
    /// The `AVFileType` raw value, e.g. "com.apple.quicktime-movie".
    let fileType: String?
    let optimizeForNetwork: Bool
    let videoBitrate: Int?
    let audioBitrate: Int?
    /// The integrated loudness target the written file is normalised to, in
    /// LUFS (`export_overrides.rs`'s `loudness_lufs`, −70…0), or nil for "do
    /// not normalise" — which is what an ABSENT key means, the same rule the
    /// two bitrates follow. The export sheet's Loudness popup and the
    /// `export` tool are the two callers that set it.
    let loudnessLufs: Double?
    /// The true-peak ceiling of the export's master limiter, in dBTP
    /// (`peak_dbtp`, −20…0, spec §11 AU-27), with or without a target; nil
    /// when not asked, and the master then holds −1 dBTP
    /// (`masterCeilingDBTP`).
    let peakDbtp: Double?
    /// Whether this ENCODING carries an alpha channel — true for `prores_4444`,
    /// `hevc_alpha`, `vp9_alpha_webm` and `apng`, and for nothing else the table offers.
    ///
    /// The rows are not alike and `apng`'s is the one to remember beside it:
    /// `gif` is FALSE though a GIF can show a transparent pixel, because one
    /// palette index is not a channel and nothing partial survives it, where
    /// APNG carries a real fourth channel (`export_table.rs`'s field doc is
    /// where that argument lives, and the header repeats it). A reader who
    /// takes this for `prores_4444` alone reads the export sheet's footnote
    /// and the Document tab's note as bugs — which is what the phase's own
    /// review found this sentence doing.
    ///
    /// **It is a capability of the row, NOT a statement about the project**,
    /// and the obvious reading of the name is the wrong one. `export_settings`
    /// resolves one flat object for every row alike, so a flag derived from
    /// the canvas background would report `alpha: true` on an H.264, a GIF
    /// and a WAV, none of which can hold one. It follows `audio`'s own
    /// precedent in `export_table.rs`: "a fact about the CONTAINER rather
    /// than a decision about the project". A translucent canvas is a
    /// separate, orthogonal fact, and what this answers is whether the file
    /// would keep it.
    let alpha: Bool
    /// The picture the file is written as and tagged with (spec §11 HD-14
    /// (c), `export.rs`): in an HLG project `"hlg"` (an HDR row's default),
    /// `"pq"` (HDR10) or `"sdr"` (the SDR version, every other video row's);
    /// nil — today's tags — for every SDR project and every audio row, whose
    /// settings carry no key.
    let color: String?
    /// The bundled encoder that writes the video (`writer`, "svt_av1" or
    /// "libvpx", spec §11 CX-12, CX-16) and its speed (`encoder_speed`, on
    /// the AV1 rows alone); nil on every row AVFoundation encodes, whose
    /// settings carry neither key.
    let writer: String?
    let encoderSpeed: EncoderSpeed?
    /// The sound's bit depth (`audio_bits`, spec §11 AU-29): 16 or 24 on
    /// `audio_wav` and `audio_aiff`, whose settings always carry it; nil on
    /// every other row, whose master writes 16.
    let audioBits: Int?
    /// The stems written beside the mix (`stems`, spec §11 AU-108), in order;
    /// empty when not asked, whose settings carry no key.
    let stems: [ExportStem]

    /// The master limiter's ceiling (spec §11 AU-27): `peakDbtp`, else
    /// `ExportLoudness.defaultCeiling`.
    var masterCeilingDBTP: Double { peakDbtp ?? ExportLoudness.defaultCeiling }

    /// `color` as the picture it names; nil when the settings carry none.
    var dynamicRange: DynamicRange? { color.flatMap(DynamicRange.init(rawValue:)) }

    /// Spelled out rather than synthesized because two keys do not follow
    /// from the property names: the core nests the resolved range under
    /// `range` (`export.rs`), and its preset name is `avf_preset`, which
    /// `.convertFromSnakeCase` turns into `avfPreset`. Decoding those as
    /// `start` / `duration` / `avPreset` silently produced a zero-length
    /// range — which disabled the export sheet's Export button and made the
    /// agent's `export` report `"duration": 0` — and threw the core's
    /// AVFoundation preset away.
    ///
    /// The two loudness keys are NOT of that kind: `loudness_lufs` and
    /// `peak_dbtp` convert to `loudnessLufs` and `peakDbtp` on their own.
    /// They are listed for the reason every other well-behaved key is —
    /// a `CodingKeys` enum is exhaustive, and a case left out is a field
    /// that silently decodes as nil. `alpha` (phase 7) is the newest of
    /// those, and it decodes as FALSE when left out, which would have read
    /// as "no row can carry alpha" — a defect that looks like a working
    /// build.
    ///
    /// **Two keys the core emits are still absent, deliberately: `audio` and
    /// `video`.** Nothing decodes them, so adding cases would add two stored
    /// properties no reader consults; `isAudioOnly` answers the same question
    /// from `avPreset` and the container and predates both. `alpha` is the
    /// first of the three anything actually reads, which is why it is the
    /// only one here. A future reader of `audio` or `video` adds the case —
    /// it does not infer the answer from this list's silence.
    private enum CodingKeys: String, CodingKey {
        case preset, container, codec, width, height, fps, range
        case avPreset = "avfPreset"
        case fileType, optimizeForNetwork, videoBitrate, audioBitrate
        case loudnessLufs, peakDbtp, alpha, color, writer, encoderSpeed, audioBits, stems
    }

    private enum RangeKeys: String, CodingKey {
        case start, duration
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        preset = c.lenient(.preset, "")
        container = c.lenient(.container, "mov")
        codec = c.lenient(.codec, "h264")
        width = c.lenient(.width, 1920)
        height = c.lenient(.height, 1080)
        fps = c.lenient(.fps, Fps.thirty)
        let range = try? c.nestedContainer(keyedBy: RangeKeys.self, forKey: .range)
        start = range?.lenient(.start, 0) ?? 0
        duration = range?.lenient(.duration, 0) ?? 0
        avPreset = c.lenient(.avPreset)
        fileType = c.lenient(.fileType)
        optimizeForNetwork = c.lenient(.optimizeForNetwork, true)
        videoBitrate = c.lenient(.videoBitrate)
        audioBitrate = c.lenient(.audioBitrate)
        loudnessLufs = c.lenient(.loudnessLufs)
        peakDbtp = c.lenient(.peakDbtp)
        // False is the safe default: only `prores_4444`, `hevc_alpha`,
        // `vp9_alpha_webm` and `apng` answer true, and a core that predates phase 7 does not emit
        // the key at all. Its silence UNDER-reports — that core has no
        // `prores_4444` row to describe, but its `apng` row wrote alpha then as it does
        // now — and under-reporting is the direction that cannot hurt: this
        // key only ADDS the footnote's "alpha" and ARMS
        // `ExportWriter.checkAlphaSurvivesTheSize`, so false promises less
        // than the file holds where true would promise more.
        alpha = c.lenient(.alpha, false)
        color = c.lenient(.color)
        writer = c.lenient(.writer)
        let speed: String? = c.lenient(.encoderSpeed)
        encoderSpeed = speed.flatMap(EncoderSpeed.init(rawValue:))
        audioBits = c.lenient(.audioBits)
        stems = c.lenient(.stems, [])
    }

    var renderSize: CGSize { CGSize(width: width, height: height) }
}

extension ExportSettings {
    /// Whether an encoding's sound is LPCM: the `lpcm` codec of the
    /// uncompressed audio rows, and every ProRes profile, which §7.8 pairs
    /// with uncompressed sound. The export sheet's fixed-rate rows
    /// (`ExportSheetController.Applies`) and the writer's audio settings
    /// (`ExportWriter.audioSettings`) both ask it.
    static func carriesLinearPCM(codec: String) -> Bool {
        let c = codec.lowercased()
        return c == "lpcm" || c.hasPrefix("prores")
    }
}

/// A bundled encoder's speed (spec §11 CX-2, CX-12 (2)): the core's word, the
/// sheet's name and SVT-AV1's preset.
enum EncoderSpeed: String, CaseIterable {
    case faster, balanced, smaller

    var menuName: String {
        switch self {
        case .faster: return "Faster"
        case .balanced: return "Balanced"
        case .smaller: return "Smaller file"
        }
    }

    var svtPreset: Int8 {
        switch self {
        case .faster: return 8
        case .balanced: return 6
        case .smaller: return 4
        }
    }
}

/// One row of the export sheet's Size popup, from `rc_export_sizes`: the
/// document's own size, an image format's cap, or a standard size fitted to
/// the document's aspect.
struct ExportSize: Decodable, Equatable, Identifiable {
    /// "document", "preset" (an image format's cap), "2160p", "1440p",
    /// "1080p" or "720p" — the vocabulary the `export` tool's `size` takes.
    let id: String
    /// "Document size" (or "Document (even)"), "GIF default", "4K"… — the
    /// sheet appends the numbers.
    let name: String
    let width: Int
    let height: Int
}
import Foundation

/// The export sheet's CONTROL CHOICES as a value, and the two places they are
/// kept: the last one used (`UserDefaults`) and the named ones a person saves
/// (`~/Library/Application Support/Frame Job/ExportPresets.json`).
///
/// **A stored preset is what the CONTROLS said, never what the core resolved,
/// and that is the whole design.** Road map 2's phase 7 asks for "a name →
/// overrides map … resolved by the core's `export_settings` like any
/// overrides, so the core never learns about them". The last clause stands and
/// is why this file has no `rc_*` call in it and needs none. The first cannot
/// be built, for two independent reasons:
///
/// 1. **The encoding is not an override.** `rc_export_settings` takes the
///    preset id as a separate ARGUMENT, and `export_overrides.rs` has no
///    `preset` key — it ignores a key it does not know, silently, on purpose —
///    so a map that carried the format would drop it and every preset would
///    resolve as H.264.
/// 2. **A resolved map cannot restore the sheet.** The Quality popup stores a
///    bits-per-pixel TIER and derives a bit rate at pick time from the frame
///    the controls are asking for; the Size popup stores a ROW ID
///    (`export_size.rs`'s vocabulary). Handed back
///    `{width: 1920, height: 1080, video_bitrate: 8000000}` the sheet cannot
///    tell "1080p + High" from "Custom 1920 × 1080 + a typed rate" — and
///    re-applying an absolute bit rate on a document of another size silently
///    changes what "High" meant, which is exactly what a tier expressed in
///    bits per PIXEL exists to prevent.
///
/// So a preset is the row of choices a person made, and applying one is the
/// same code path as picking each control by hand: `ExportSheetController`'s
/// `apply(_:)` writes the controls, `overrides()` turns them into the core's
/// object, and `rc_export_settings` answers. Nothing here computes a size, a
/// rate or a duration, which is the §7 rule the whole sheet is built on.
///
/// The consequence worth knowing, because it is a FEATURE: a preset saved on a
/// 1080p document and applied to a 4K one exports 4K at the tier's rate for
/// 4K. It remembers the request, not the answer.
struct ExportChoice: Codable, Equatable {
    /// The preset's name as the popup lists it. Empty for the remembered
    /// choice, which is nobody's preset and is never listed — the field is
    /// part of the record because the FILE's shape is a flat list of named
    /// choices, and splitting the type in two to keep one string out of one
    /// of its two homes would buy nothing.
    var name: String = ""

    /// `ExportPreset.id` — the core's own vocabulary for the encoding
    /// (`export_table.rs`), so a row renamed in the table still restores.
    var presetID: String = ""

    /// `ExportSize.id` — "document", "1080p", "preset"… — and never an
    /// INDEX. `visibleSizes` drops every row whose numbers an earlier row
    /// already has, so index 2 names a different size on a vertical document
    /// than on a landscape one; the id is stable across both.
    var sizeRow: String?

    /// `[width, height]` when "Custom…" was chosen. Exclusive with
    /// `sizeRow` in practice, and if a hand-edited file carries both the row
    /// wins, because a row is a thing the sheet can select and a custom size
    /// is only reachable through it.
    var customSize: [Int]?

    /// `[num, den]`, or nil for "Project rate" — the popup's first row, which
    /// is no override at all.
    var fps: [Int]?

    /// `QualityTier.name` ("Low", "Medium", "High", "Maximum"), or nil for
    /// "Format default". The NAME and not the derived bit rate: see the type
    /// doc's second reason.
    var qualityTier: String?

    /// The integrated loudness target in LUFS, or nil for "Off".
    ///
    /// The number rather than the popup ROW, though the contract allows
    /// either. Restoring picks the matching row when there is one and
    /// "Custom…" otherwise, so a target of −16 comes back as the −16 row even
    /// if it was typed into the Custom field. That is a difference in which
    /// control is lit and in nothing else: `overrides()` reads the same
    /// number out of either state, so the file that gets written is
    /// identical, and one number cannot disagree with itself the way a row
    /// plus a value can.
    var loudness: Double?

    /// True for "In/out range". Degrades to "Whole project" on a document
    /// that has no range — the popup only carries that row when it does.
    var inOutRange: Bool = false

    /// The burn-in checkbox. It is a RECIPE option rather than an export
    /// override (`RecipeOptions`), but from this sheet's side it is one more
    /// control, and a preset that remembered every choice but that one would
    /// be a preset that quietly stopped burning in.
    var burnInTimecode: Bool = false

    /// The Speed popup's last word (`EncoderSpeed`, spec §11 CX-12 (2)), stored on every
    /// row so the popup keeps it across formats; only `av1` sends it.
    var encoderSpeed: String?

    /// The Bit depth popup's last choice (16 or 24, spec §11 AU-29), stored on every row so
    /// the popup keeps it across formats; only `audio_wav` and `audio_aiff` send it.
    var audioBits: Int?

    /// The Stems popup's last word ("tracks" or "names", nil for None, spec §11 AU-108),
    /// stored on every row so the popup keeps it across formats; only the audio rows send it.
    var stems: String?

    /// The file's spelling. Snake case because a person can open
    /// `ExportPresets.json` in an editor, and because `burn_in_timecode` is
    /// then the same string the core's recipe options use — one name for one
    /// idea, even across the FFI it never crosses.
    private enum CodingKeys: String, CodingKey {
        case name
        case presetID = "preset_id"
        case sizeRow = "size_row"
        case customSize = "custom_size"
        case fps
        case qualityTier = "quality_tier"
        case loudness
        case inOutRange = "in_out_range"
        case burnInTimecode = "burn_in_timecode"
        case encoderSpeed = "encoder_speed"
        case audioBits = "audio_bits"
        case stems
    }

    init(
        name: String = "", presetID: String = "", sizeRow: String? = nil,
        customSize: [Int]? = nil, fps: [Int]? = nil, qualityTier: String? = nil,
        loudness: Double? = nil, inOutRange: Bool = false, burnInTimecode: Bool = false,
        encoderSpeed: String? = nil, audioBits: Int? = nil, stems: String? = nil
    ) {
        self.name = name
        self.presetID = presetID
        self.sizeRow = sizeRow
        self.customSize = customSize
        self.fps = fps
        self.qualityTier = qualityTier
        self.loudness = loudness
        self.inOutRange = inOutRange
        self.burnInTimecode = burnInTimecode
        self.encoderSpeed = encoderSpeed
        self.audioBits = audioBits
        self.stems = stems
    }

    /// Every key optional, every absence a default.
    ///
    /// Written by hand rather than synthesized because the synthesized
    /// decoder THROWS on a missing non-optional, and this record is read from
    /// a file a person can edit and from a defaults value an older build
    /// wrote. One missing `burn_in_timecode` would otherwise fail the whole
    /// array's decode and take every other preset down with it — the shape of
    /// failure `load()` promises never to have.
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        name = (try? c.decodeIfPresent(String.self, forKey: .name)) ?? ""
        presetID = (try? c.decodeIfPresent(String.self, forKey: .presetID)) ?? ""
        sizeRow = try? c.decodeIfPresent(String.self, forKey: .sizeRow)
        customSize = try? c.decodeIfPresent([Int].self, forKey: .customSize)
        fps = try? c.decodeIfPresent([Int].self, forKey: .fps)
        qualityTier = try? c.decodeIfPresent(String.self, forKey: .qualityTier)
        loudness = try? c.decodeIfPresent(Double.self, forKey: .loudness)

        codec = c.lenient(.codec, "h264")
        let size: [Int]? = c.lenient(.size)
        width = size?.count == 2 ? size?[0] : nil
        height = size?.count == 2 ? size?[1] : nil
        audioOnly = !c.lenient(.video, true)
        carriesHDR = c.lenient(.hdr, false)
        let speeds: [String] = c.lenient(.encoderSpeeds, [])
        encoderSpeeds = speeds.compactMap(EncoderSpeed.init(rawValue:))
        writer = c.lenient(.writer)
        audioBits = c.lenient(.audioBits, [])
        stems = c.lenient(.stems, [])
    }
}

/// One stem an audio export writes beside its mix (spec §11 AU-108): its file
/// name's tail and the timeline track ids it holds, as the core resolved them.
struct ExportStem: Decodable, Equatable {
    let name: String
    let tracks: [UInt32]
}

/// A preset plus overrides resolved against the project into the concrete
/// numbers `Exporter` configures its pipeline with — `ExportWriter` or the
/// ImageIO frame sequence (§7.8).
struct ExportSettings: Decodable, Equatable {
    let preset: String
    let container: String
    let codec: String
    let width: Int
    let height: Int
    let fps: Fps
    /// The range to write — the whole timeline, or the in/out range.
    let start: Ticks
    let duration: Ticks
    /// The `AVAssetExportSession` preset name the row carries for the
    /// record; nil is the signal that AVFoundation cannot write this
    /// container and the frames go through ImageIO (`isImageSequence`).
    let avPreset: String?
    /// The `AVFileType` raw value, e.g. "com.apple.quicktime-movie".
    let fileType: String?
    let optimizeForNetwork: Bool
    let videoBitrate: Int?
    let audioBitrate: Int?
    /// The integrated loudness target the written file is normalised to, in
    /// LUFS (`export_overrides.rs`'s `loudness_lufs`, −70…0), or nil for "do
    /// not normalise" — which is what an ABSENT key means, the same rule the
    /// two bitrates follow. The export sheet's Loudness popup and the
    /// `export` tool are the two callers that set it.
    let loudnessLufs: Double?
    /// The true-peak ceiling of the export's master limiter, in dBTP
    /// (`peak_dbtp`, −20…0, spec §11 AU-27), with or without a target; nil
    /// when not asked, and the master then holds −1 dBTP
    /// (`masterCeilingDBTP`).
    let peakDbtp: Double?
    /// Whether this ENCODING carries an alpha channel — true for `prores_4444`,
    /// `hevc_alpha`, `vp9_alpha_webm` and `apng`, and for nothing else the table offers.
    ///
    /// The rows are not alike and `apng`'s is the one to remember beside it:
    /// `gif` is FALSE though a GIF can show a transparent pixel, because one
    /// palette index is not a channel and nothing partial survives it, where
    /// APNG carries a real fourth channel (`export_table.rs`'s field doc is
    /// where that argument lives, and the header repeats it). A reader who
    /// takes this for `prores_4444` alone reads the export sheet's footnote
    /// and the Document tab's note as bugs — which is what the phase's own
    /// review found this sentence doing.
    ///
    /// **It is a capability of the row, NOT a statement about the project**,
    /// and the obvious reading of the name is the wrong one. `export_settings`
    /// resolves one flat object for every row alike, so a flag derived from
    /// the canvas background would report `alpha: true` on an H.264, a GIF
    /// and a WAV, none of which can hold one. It follows `audio`'s own
    /// precedent in `export_table.rs`: "a fact about the CONTAINER rather
    /// than a decision about the project". A translucent canvas is a
    /// separate, orthogonal fact, and what this answers is whether the file
    /// would keep it.
    let alpha: Bool
    /// The picture the file is written as and tagged with (spec §11 HD-14
    /// (c), `export.rs`): in an HLG project `"hlg"` (an HDR row's default),
    /// `"pq"` (HDR10) or `"sdr"` (the SDR version, every other video row's);
    /// nil — today's tags — for every SDR project and every audio row, whose
    /// settings carry no key.
    let color: String?
    /// The bundled encoder that writes the video (`writer`, "svt_av1" or
    /// "libvpx", spec §11 CX-12, CX-16) and its speed (`encoder_speed`, on
    /// the AV1 rows alone); nil on every row AVFoundation encodes, whose
    /// settings carry neither key.
    let writer: String?
    let encoderSpeed: EncoderSpeed?
    /// The sound's bit depth (`audio_bits`, spec §11 AU-29): 16 or 24 on
    /// `audio_wav` and `audio_aiff`, whose settings always carry it; nil on
    /// every other row, whose master writes 16.
    let audioBits: Int?
    /// The stems written beside the mix (`stems`, spec §11 AU-108), in order;
    /// empty when not asked, whose settings carry no key.
    let stems: [ExportStem]

    /// The master limiter's ceiling (spec §11 AU-27): `peakDbtp`, else
    /// `ExportLoudness.defaultCeiling`.
    var masterCeilingDBTP: Double { peakDbtp ?? ExportLoudness.defaultCeiling }

    /// `color` as the picture it names; nil when the settings carry none.
    var dynamicRange: DynamicRange? { color.flatMap(DynamicRange.init(rawValue:)) }

    /// Spelled out rather than synthesized because two keys do not follow
    /// from the property names: the core nests the resolved range under
    /// `range` (`export.rs`), and its preset name is `avf_preset`, which
    /// `.convertFromSnakeCase` turns into `avfPreset`. Decoding those as
    /// `start` / `duration` / `avPreset` silently produced a zero-length
    /// range — which disabled the export sheet's Export button and made the
    /// agent's `export` report `"duration": 0` — and threw the core's
    /// AVFoundation preset away.
    ///
    /// The two loudness keys are NOT of that kind: `loudness_lufs` and
    /// `peak_dbtp` convert to `loudnessLufs` and `peakDbtp` on their own.
    /// They are listed for the reason every other well-behaved key is —
    /// a `CodingKeys` enum is exhaustive, and a case left out is a field
    /// that silently decodes as nil. `alpha` (phase 7) is the newest of
    /// those, and it decodes as FALSE when left out, which would have read
    /// as "no row can carry alpha" — a defect that looks like a working
    /// build.
    ///
    /// **Two keys the core emits are still absent, deliberately: `audio` and
    /// `video`.** Nothing decodes them, so adding cases would add two stored
    /// properties no reader consults; `isAudioOnly` answers the same question
    /// from `avPreset` and the container and predates both. `alpha` is the
    /// first of the three anything actually reads, which is why it is the
    /// only one here. A future reader of `audio` or `video` adds the case —
    /// it does not infer the answer from this list's silence.
    private enum CodingKeys: String, CodingKey {
        case preset, container, codec, width, height, fps, range
        case avPreset = "avfPreset"
        case fileType, optimizeForNetwork, videoBitrate, audioBitrate
        case loudnessLufs, peakDbtp, alpha, color, writer, encoderSpeed, audioBits, stems
    }

    private enum RangeKeys: String, CodingKey {
        case start, duration
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        preset = c.lenient(.preset, "")
        container = c.lenient(.container, "mov")
        codec = c.lenient(.codec, "h264")
        width = c.lenient(.width, 1920)
        height = c.lenient(.height, 1080)
        fps = c.lenient(.fps, Fps.thirty)
        let range = try? c.nestedContainer(keyedBy: RangeKeys.self, forKey: .range)
        start = range?.lenient(.start, 0) ?? 0
        duration = range?.lenient(.duration, 0) ?? 0
        avPreset = c.lenient(.avPreset)
        fileType = c.lenient(.fileType)
        optimizeForNetwork = c.lenient(.optimizeForNetwork, true)
        videoBitrate = c.lenient(.videoBitrate)
        audioBitrate = c.lenient(.audioBitrate)
        loudnessLufs = c.lenient(.loudnessLufs)
        peakDbtp = c.lenient(.peakDbtp)
        // False is the safe default: only `prores_4444`, `hevc_alpha`,
        // `vp9_alpha_webm` and `apng` answer true, and a core that predates phase 7 does not emit
        // the key at all. Its silence UNDER-reports — that core has no
        // `prores_4444` row to describe, but its `apng` row wrote alpha then as it does
        // now — and under-reporting is the direction that cannot hurt: this
        // key only ADDS the footnote's "alpha" and ARMS
        // `ExportWriter.checkAlphaSurvivesTheSize`, so false promises less
        // than the file holds where true would promise more.
        alpha = c.lenient(.alpha, false)
        color = c.lenient(.color)
        writer = c.lenient(.writer)
        let speed: String? = c.lenient(.encoderSpeed)
        encoderSpeed = speed.flatMap(EncoderSpeed.init(rawValue:))
        audioBits = c.lenient(.audioBits)
        stems = c.lenient(.stems, [])
    }

    var renderSize: CGSize { CGSize(width: width, height: height) }
}

extension ExportSettings {
    /// Whether an encoding's sound is LPCM: the `lpcm` codec of the
    /// uncompressed audio rows, and every ProRes profile, which §7.8 pairs
    /// with uncompressed sound. The export sheet's fixed-rate rows
    /// (`ExportSheetController.Applies`) and the writer's audio settings
    /// (`ExportWriter.audioSettings`) both ask it.
    static func carriesLinearPCM(codec: String) -> Bool {
        let c = codec.lowercased()
        return c == "lpcm" || c.hasPrefix("prores")
    }
}

/// A bundled encoder's speed (spec §11 CX-2, CX-12 (2)): the core's word, the
/// sheet's name and SVT-AV1's preset.
enum EncoderSpeed: String, CaseIterable {
    case faster, balanced, smaller

    var menuName: String {
        switch self {
        case .faster: return "Faster"
        case .balanced: return "Balanced"
        case .smaller: return "Smaller file"
        }
    }

    var svtPreset: Int8 {
        switch self {
        case .faster: return 8
        case .balanced: return 6
        case .smaller: return 4
        }
    }
}

/// One row of the export sheet's Size popup, from `rc_export_sizes`: the
/// document's own size, an image format's cap, or a standard size fitted to
/// the document's aspect.
struct ExportSize: Decodable, Equatable, Identifiable {
    /// "document", "preset" (an image format's cap), "2160p", "1440p",
    /// "1080p" or "720p" — the vocabulary the `export` tool's `size` takes.
    let id: String
    /// "Document size" (or "Document (even)"), "GIF default", "4K"… — the
    /// sheet appends the numbers.
    let name: String
    let width: Int
    let height: Int
}
import Foundation

/// The export sheet's CONTROL CHOICES as a value, and the two places they are
/// kept: the last one used (`UserDefaults`) and the named ones a person saves
/// (`~/Library/Application Support/Frame Job/ExportPresets.json`).
///
/// **A stored preset is what the CONTROLS said, never what the core resolved,
/// and that is the whole design.** Road map 2's phase 7 asks for "a name →
/// overrides map … resolved by the core's `export_settings` like any
/// overrides, so the core never learns about them". The last clause stands and
/// is why this file has no `rc_*` call in it and needs none. The first cannot
/// be built, for two independent reasons:
///
/// 1. **The encoding is not an override.** `rc_export_settings` takes the
///    preset id as a separate ARGUMENT, and `export_overrides.rs` has no
///    `preset` key — it ignores a key it does not know, silently, on purpose —
///    so a map that carried the format would drop it and every preset would
///    resolve as H.264.
/// 2. **A resolved map cannot restore the sheet.** The Quality popup stores a
///    bits-per-pixel TIER and derives a bit rate at pick time from the frame
///    the controls are asking for; the Size popup stores a ROW ID
///    (`export_size.rs`'s vocabulary). Handed back
///    `{width: 1920, height: 1080, video_bitrate: 8000000}` the sheet cannot
///    tell "1080p + High" from "Custom 1920 × 1080 + a typed rate" — and
///    re-applying an absolute bit rate on a document of another size silently
///    changes what "High" meant, which is exactly what a tier expressed in
///    bits per PIXEL exists to prevent.
///
/// So a preset is the row of choices a person made, and applying one is the
/// same code path as picking each control by hand: `ExportSheetController`'s
/// `apply(_:)` writes the controls, `overrides()` turns them into the core's
/// object, and `rc_export_settings` answers. Nothing here computes a size, a
/// rate or a duration, which is the §7 rule the whole sheet is built on.
///
/// The consequence worth knowing, because it is a FEATURE: a preset saved on a
/// 1080p document and applied to a 4K one exports 4K at the tier's rate for
/// 4K. It remembers the request, not the answer.
struct ExportChoice: Codable, Equatable {
    /// The preset's name as the popup lists it. Empty for the remembered
    /// choice, which is nobody's preset and is never listed — the field is
    /// part of the record because the FILE's shape is a flat list of named
    /// choices, and splitting the type in two to keep one string out of one
    /// of its two homes would buy nothing.
    var name: String = ""

    /// `ExportPreset.id` — the core's own vocabulary for the encoding
    /// (`export_table.rs`), so a row renamed in the table still restores.
    var presetID: String = ""

    /// `ExportSize.id` — "document", "1080p", "preset"… — and never an
    /// INDEX. `visibleSizes` drops every row whose numbers an earlier row
    /// already has, so index 2 names a different size on a vertical document
    /// than on a landscape one; the id is stable across both.
    var sizeRow: String?

    /// `[width, height]` when "Custom…" was chosen. Exclusive with
    /// `sizeRow` in practice, and if a hand-edited file carries both the row
    /// wins, because a row is a thing the sheet can select and a custom size
    /// is only reachable through it.
    var customSize: [Int]?

    /// `[num, den]`, or nil for "Project rate" — the popup's first row, which
    /// is no override at all.
    var fps: [Int]?

    /// `QualityTier.name` ("Low", "Medium", "High", "Maximum"), or nil for
    /// "Format default". The NAME and not the derived bit rate: see the type
    /// doc's second reason.
    var qualityTier: String?

    /// The integrated loudness target in LUFS, or nil for "Off".
    ///
    /// The number rather than the popup ROW, though the contract allows
    /// either. Restoring picks the matching row when there is one and
    /// "Custom…" otherwise, so a target of −16 comes back as the −16 row even
    /// if it was typed into the Custom field. That is a difference in which
    /// control is lit and in nothing else: `overrides()` reads the same
    /// number out of either state, so the file that gets written is
    /// identical, and one number cannot disagree with itself the way a row
    /// plus a value can.
    var loudness: Double?

    /// True for "In/out range". Degrades to "Whole project" on a document
    /// that has no range — the popup only carries that row when it does.
    var inOutRange: Bool = false

    /// The burn-in checkbox. It is a RECIPE option rather than an export
    /// override (`RecipeOptions`), but from this sheet's side it is one more
    /// control, and a preset that remembered every choice but that one would
    /// be a preset that quietly stopped burning in.
    var burnInTimecode: Bool = false

    /// The Speed popup's last word (`EncoderSpeed`, spec §11 CX-12 (2)), stored on every
    /// row so the popup keeps it across formats; only `av1` sends it.
    var encoderSpeed: String?

    /// The Bit depth popup's last choice (16 or 24, spec §11 AU-29), stored on every row so
    /// the popup keeps it across formats; only `audio_wav` and `audio_aiff` send it.
    var audioBits: Int?

    /// The Stems popup's last word ("tracks" or "names", nil for None, spec §11 AU-108),
    /// stored on every row so the popup keeps it across formats; only the audio rows send it.
    var stems: String?

    /// The file's spelling. Snake case because a person can open
    /// `ExportPresets.json` in an editor, and because `burn_in_timecode` is
    /// then the same string the core's recipe options use — one name for one
    /// idea, even across the FFI it never crosses.
    private enum CodingKeys: String, CodingKey {
        case name
        case presetID = "preset_id"
        case sizeRow = "size_row"
        case customSize = "custom_size"
        case fps
        case qualityTier = "quality_tier"
        case loudness
        case inOutRange = "in_out_range"
        case burnInTimecode = "burn_in_timecode"
        case encoderSpeed = "encoder_speed"
        case audioBits = "audio_bits"
        case stems
    }

    init(
        name: String = "", presetID: String = "", sizeRow: String? = nil,
        customSize: [Int]? = nil, fps: [Int]? = nil, qualityTier: String? = nil,
        loudness: Double? = nil, inOutRange: Bool = false, burnInTimecode: Bool = false,
        encoderSpeed: String? = nil, audioBits: Int? = nil, stems: String? = nil
    ) {
        self.name = name
        self.presetID = presetID
        self.sizeRow = sizeRow
        self.customSize = customSize
        self.fps = fps
        self.qualityTier = qualityTier
        self.loudness = loudness
        self.inOutRange = inOutRange
        self.burnInTimecode = burnInTimecode
        self.encoderSpeed = encoderSpeed
        self.audioBits = audioBits
        self.stems = stems
    }

    /// Every key optional, every absence a default.
    ///
    /// Written by hand rather than synthesized because the synthesized
    /// decoder THROWS on a missing non-optional, and this record is read from
    /// a file a person can edit and from a defaults value an older build
    /// wrote. One missing `burn_in_timecode` would otherwise fail the whole
    /// array's decode and take every other preset down with it — the shape of
    /// failure `load()` promises never to have.
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        name = (try? c.decodeIfPresent(String.self, forKey: .name)) ?? ""
        presetID = (try? c.decodeIfPresent(String.self, forKey: .presetID)) ?? ""
        sizeRow = try? c.decodeIfPresent(String.self, forKey: .sizeRow)
        customSize = try? c.decodeIfPresent([Int].self, forKey: .customSize)
        fps = try? c.decodeIfPresent([Int].self, forKey: .fps)
        qualityTier = try? c.decodeIfPresent(String.self, forKey: .qualityTier)
        loudness = try? c.decodeIfPresent(Double.self, forKey: .loudness)

import AVFoundation

extension Exporter {

    /// Why an export stopped. Every case is reported through `completion` —
    /// nothing here throws at the caller and nothing crashes.
    enum ExportError: LocalizedError {
        /// The core could not produce a composition plan for this project.
        case noPlan
        /// Nothing to write: no video and no audio track in the plan. Reached
        /// by an empty timeline AND by one holding only text, shapes and
        /// images, which need no composition track (spec §7.2) — so the
        /// message has to name the second case, which is the surprising one.
        case emptyTimeline
        /// This Mac will not encode what the core's preset resolved to — an
        /// unknown codec name, one `AVAssetWriter` refuses an input for, or
        /// one whose encoder is not found when the write starts
        /// (`Exporter.encoderOutcome`). Carries the preset id when the core
        /// gave one, else the codec.
        case presetUnavailable(String)
        /// The settings named a container this build cannot map to a file
        /// type.
        case fileTypeUnsupported(String)
        /// An alpha-carrying row was asked for a size of a different SHAPE
        /// from the canvas, which cannot be written correctly and so is not
        /// written at all (road map 2, phase 7b). Carries the canvas and the
        /// size the core resolved, in that order.
        ///
        /// **Which sizes reach it** (spec §11 G-33 (c)): on `prores_4444` and
        /// `hevc_alpha`, a frame more than a pixel off the canvas's shape
        /// (`ExportWriter.shapeGap`: `gap > limit`). A frame within a pixel is
        /// filled instead of padded and is written — the evened Document row
        /// on a canvas with an odd edge, a standard row whose long edge
        /// rounded, a size typed in the canvas's own proportions (evened
        /// first on `hevc_alpha`, so an odd one is written a pixel smaller),
        /// and on `prores_4444` a typed frame one pixel short. So no size of
        /// the canvas's shape is refused for being odd; a typed size of any
        /// other shape is judged as the even frame it becomes
        /// (1279 × 720 on 1920 × 1080 is 1278 × 720 on `hevc_alpha`, and
        /// refused).
        ///
        /// **Measured, not feared.** `AVVideoScalingModeResizeAspect` pads
        /// the frame to the asked-for shape, and the padding path destroys
        /// the alpha channel: a 320 × 180 transparent canvas written
        /// `prores_4444` at 240 × 240 comes back with the PICTURE at alpha 0
        /// and the letterbox BARS at alpha 255 — the answer inverted, not
        /// merely lost. The same canvas at 160 × 90 or 640 × 360 is correct
        /// at every pixel, so the fault is the padding and nothing else.
        ///
        /// It is refused rather than documented because the file would be
        /// silently wrong in the one respect the row exists for, and this
        /// codebase's rule for exactly that shape is `codecType(for:)`'s:
        /// a refusal, never a fallback that puts a file on disk which is not
        /// the one asked for. Nothing legitimate is blocked by accident —
        /// every row of the Size popup is fitted to the document's own
        /// aspect (`export_size.rs`), so only a hand-typed Custom size of
        /// another shape can reach this (or a canvas, or a typed size, with
        /// an edge of exactly 1 px, raised to 2 on `hevc_alpha`), and the
        /// message says what to type instead: every size with the canvas's
        /// proportions is written, odd or even, smaller or larger.
        case alphaAspectMismatch(width: Int, height: Int, wantWidth: Int, wantHeight: Int)
        /// The user pressed Cancel. The sheet dismisses without an alert.
        case cancelled
        /// The write ended in a state that is neither completed nor
        /// cancelled and had no error of its own — or one of the reader's or
        /// writer's own steps refused with a message worth showing.
        case failed(String)
        /// Graphic clips in the range whose module does not compile, or is
        /// not in `graphics/`, each with what is wrong: the export was refused
        /// before it started (G-8). Sorted by name.
        case graphicsNotCompiled([(name: String, message: String)])
        /// A graphic failed while the export drew it, at its own frame — nil
        /// when it did not compile. The export stopped and its file is gone.
        case graphicFailed(name: String, frame: Int?, message: String)
        /// A ramped clip's audio render failed (spec §11 SR-12 (g), (h)): the
        /// export waits for every ramp segment it plays and never writes one
        /// silent, so it stops, naming the clip and the renderer's reason.
        case rampAudioFailed(clip: UInt32, message: String)
        /// A clip's isolated voice (spec §11 AU-57) could not be rendered: the
        /// export waits for it as for a ramp, and stops naming the clip.
        case isolationFailed(clip: UInt32, message: String)
        /// A gated or de-essed clip's loudness was still not measured when the
        /// export's wait ran out (spec §11 AU-42): its thresholds are relative
        /// to it, so the export stops naming the clip rather than writing it
        /// ungated.
        case loudnessUnmeasured(clip: UInt32)
        /// A clip's voice effect (spec §11 AU-147) could not be rendered: the
        /// export waits for it as for its isolation, and stops naming the clip.
        case voiceFailed(clip: UInt32, message: String)
        /// A cut-out clip's person masks (spec §11 CO-6, CO-22 (e)), or a
        /// picture's foreground masks (`foreground`, CO-106), could not be made:
        /// the export waits for every mask it draws, a picture's too, and stops
        /// naming the clip rather than writing it uncut.
        case cutoutFailed(clip: UInt32, message: String, foreground: Bool = false)

        var errorDescription: String? {
            switch self {
            case .noPlan:
                return "The project could not be prepared for export."
            case .emptyTimeline:
                return "There is nothing on the timeline to export — add a clip first."
            case .presetUnavailable(let name):
                return "This Mac cannot export with the “\(name)” preset."
            case .fileTypeUnsupported(let container):
                return "“\(container)” is not a container this build can write."
            case .alphaAspectMismatch(let width, let height, let wantWidth, let wantHeight):
                return "An export that keeps transparency has to have the canvas's own shape. "
                    + "This canvas is \(width) × \(height) and \(wantWidth) × \(wantHeight) is a "
                    + "different shape, so the picture would be padded and the padding loses the "
                    + "alpha channel. Export at \(width) × \(height), at one of the sizes in the "
                    + "popup, or at any size with the same proportions."
            case .cancelled:
                return "The export was cancelled."
            case .failed(let message):
                return message
            case .graphicsNotCompiled(let refused):
                let clauses = refused.map { "the graphic \"\($0.name)\" \($0.message)" }
                return "The export was not started: " + clauses.joined(separator: "; ")
                    + ". Fix the module and export again."
            case .graphicFailed(let name, let frame?, let message):
                return "The export was stopped at frame \(frame) of the graphic \"\(name)\": "
                    + "\(message). No file was written."
            case .graphicFailed(let name, nil, let message):
                return "The export was stopped: the graphic \"\(name)\" does not compile — "
                    + "\(message). No file was written."
            case .rampAudioFailed(let clip, let message):
                return "Clip \(clip)'s retimed audio could not be rendered: \(message)."
            case .isolationFailed(let clip, let message):
                return "Clip \(clip)'s isolated voice could not be rendered: \(message)."
            case .loudnessUnmeasured(let clip):
                return "Clip \(clip)'s loudness or speech has not been measured yet, so its "
                    + "gate, leveller and de-esser cannot be set. Wait for their Status rows to "
                    + "show the clip's loudness, then export again."
            case .voiceFailed(let clip, let message):
                return "Clip \(clip)'s voice effect could not be rendered: \(message)."
            case .cutoutFailed(let clip, let message, let foreground):
                return "Clip \(clip)'s \(foreground ? "foreground" : "person") masks could not be "
                    + "made: \(message)."
            }
        }
    }

    /// What a finished write becomes when the reason it failed is that this
    /// Mac has no encoder for the row (spec §11 G-33 (e)): the preset's own
    /// sentence, and no file.
    ///
    /// `ExportWriter.addVideo` cannot see it. Measured with an encoder
    /// specification nothing satisfies, on `.hevcWithAlpha` and `.hevc`
    /// alike: `canApply` is true, the input constructs, `canAdd` is true, and
    /// `startWriting()` then fails with `AVFoundationErrorDomain` −11834
    /// ("Cannot Encode"), leaving a 0-byte file at the destination. So it is
    /// mapped here, where `startWriting` hears the pipeline: exactly that
    /// domain and code become `.presetUnavailable` with the preset's name and
    /// the file is removed, and every other result is returned as it came.
    static func encoderOutcome(
        _ result: Result<URL, any Error>, settings: ExportSettings, destination: URL
    ) -> Result<URL, any Error> {
        guard case .failure(let error) = result else { return result }
        let reason = error as NSError
        guard reason.domain == AVFoundationErrorDomain,
            reason.code == AVError.Code.encoderNotFound.rawValue
        else { return result }
        try? FileManager.default.removeItem(at: destination)
        return .failure(ExportError.presetUnavailable(ExportWriter.presetName(settings)))
    }
}
//! An HLG project's deliverables (spec §11 HD-5, HD-14): which picture an
//! export row writes — the HLG master, HDR10 (PQ) or the SDR version — and the
//! two refusals that keep a file from carrying a picture it cannot label.
//!
//! The vocabulary is three words, `hlg`, `pq` and `sdr`, spelled
//! `dynamic_range` both as an export override (`export_overrides.rs` reads it)
//! and as a recipe option (`recipe_options.rs`), because the two are one
//! decision seen from two sides: the export publishes its settings' `color` as
//! the recipe option of the key it draws, so the output pass the preview draws
//! for Show SDR Version is the one the file is written through.
//!
//! An SDR project is untouched by all of it: `deliverable` answers `None` for
//! every row there, so its settings carry no `color` and its recipes no
//! `dynamic_range`, and every SDR file and frame is the text and the bytes it
//! was.

use crate::export_table::Preset;
use crate::model::{CanvasOutput, Project};

/// The picture an HLG project's export or frame is drawn as (spec §11 HD-14).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DynamicRange {
    /// The working space itself, BT.2100 HLG: no output pass.
    Hlg,
    /// HDR10: the HLG display light at 1,000 cd/m² through ST 2084.
    Pq,
    /// The SDR version (spec §11 HD-4): the inverse of the lift with a
    /// shoulder above reference white, encoded Rec. 709.
    Sdr,
}

impl DynamicRange {
    /// The word for `text`, or `None` for anything else.
    pub fn parse(text: &str) -> Option<DynamicRange> {
        match text {
            "hlg" => Some(DynamicRange::Hlg),
            "pq" => Some(DynamicRange::Pq),
            "sdr" => Some(DynamicRange::Sdr),
            _ => None,
        }
    }

    /// The word as it is spelled in JSON.
    pub fn as_str(self) -> &'static str {
        match self {
            DynamicRange::Hlg => "hlg",
            DynamicRange::Pq => "pq",
            DynamicRange::Sdr => "sdr",
        }
    }
}

/// The rows that carry an HDR picture (spec §11 HD-5, CX-14, CX-15, CX-16):
/// the six HDR rows, each 10-bit for an HDR picture (`vp9_webm` is 8-bit only
/// at `sdr`). Every other video row of an HLG project writes the SDR version.
pub(crate) const HDR_ROWS: [&str; 6] = [
    "hevc_10bit",
    "av1",
    "av1_webm",
    "vp9_webm",
    "prores_422",
    "prores_4444",
];

impl Project {
    /// What `preset` writes for this project when `asked` was requested
    /// (spec §11 HD-14 (c)): `None` for an audio row and for every row of an
    /// SDR project (nothing to label), else the resolved picture. An audio row
    /// reads the argument and ignores it, as a bitrate on a GIF is; an SDR
    /// project takes `sdr` as nothing; `hlg` and `pq` are refused in an SDR
    /// project and on a row that is not 10-bit, each in its own sentence.
    pub(crate) fn deliverable(
        &self,
        preset: &Preset,
        asked: Option<DynamicRange>,
    ) -> Result<Option<DynamicRange>, String> {
        if !preset.video {
            return Ok(None);
        }
        let hdr_asked = asked.filter(|range| *range != DynamicRange::Sdr);
        if self.canvas.output != CanvasOutput::Hlg {
            return match hdr_asked {
                Some(range) => Err(format!(
                    "dynamic_range \"{}\" needs an HLG project; set_canvas output \"hlg\" first",
                    range.as_str()
                )),
                None => Ok(None),
            };
        }
        if HDR_ROWS.contains(&preset.id) {
            return Ok(Some(asked.unwrap_or(DynamicRange::Hlg)));
        }
        match hdr_asked {
            Some(range) => Err(format!(
                "{} is 8-bit and writes the SDR version; export dynamic_range \"{}\" as \
                 hevc_10bit, av1, av1_webm, vp9_webm, prores_422 or prores_4444",
                preset.id,
                range.as_str()
            )),
            None => Ok(Some(DynamicRange::Sdr)),
        }
    }
}
